import pg from "pg";
const { Pool } = pg;
if (!process.env.DATABASE_URL) throw new Error("DATABASE_URL must be set");
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

type Q = { topicId: number; text: string; options: string[]; correctIndex: number; explanation: string; difficulty: "easy" | "medium" | "hard" };

const questions: Q[] = [
  // ── TOPIC 1: Anatomy & Physiology ───────────────────────────────────────
  { topicId: 1, text: "The right lung has how many lobes?", options: ["Two", "Three", "Four", "Five"], correctIndex: 1, explanation: "The right lung has three lobes: upper (RUL), middle (RML), and lower (RLL). The left lung has only two lobes (LUL and LLL) to accommodate the cardiac notch.", difficulty: "easy" },
  { topicId: 1, text: "Which structure marks the bifurcation of the trachea into right and left main bronchi?", options: ["Epiglottis", "Carina", "Cricoid cartilage", "Thyroid cartilage"], correctIndex: 1, explanation: "The carina is the ridge at the tracheal bifurcation (approximately T4–T5 level). It is a key landmark — ETT tips should be 2–3 cm above it. Stimulation of the carina triggers a cough reflex.", difficulty: "easy" },
  { topicId: 1, text: "Surfactant is produced by which cells in the alveoli?", options: ["Type I pneumocytes", "Type II pneumocytes", "Alveolar macrophages", "Clara cells"], correctIndex: 1, explanation: "Type II pneumocytes (granular pneumocytes) synthesize and secrete pulmonary surfactant. Surfactant reduces alveolar surface tension, preventing collapse at end-expiration and reducing the work of breathing.", difficulty: "easy" },
  { topicId: 1, text: "Surfactant reduces alveolar surface tension according to which principle?", options: ["Boyle's law", "Dalton's law", "LaPlace's law", "Henry's law"], correctIndex: 2, explanation: "LaPlace's law: P = 2T/r. For a given surface tension T, a smaller alveolus (smaller radius r) generates higher collapsing pressure. Surfactant preferentially reduces surface tension at smaller radii, preventing small alveoli from collapsing.", difficulty: "medium" },
  { topicId: 1, text: "The diaphragm is innervated by which nerve?", options: ["Vagus nerve (CN X)", "Phrenic nerve (C3–C5)", "Intercostal nerves", "Hypoglossal nerve"], correctIndex: 1, explanation: "The phrenic nerve (C3, C4, C5 — 'keeps the diaphragm alive') innervates the diaphragm. Cervical spinal cord injury at C3 or above eliminates spontaneous breathing and requires permanent ventilatory support.", difficulty: "easy" },
  { topicId: 1, text: "During quiet inspiration, which muscle does the majority of the work?", options: ["Internal intercostals", "External intercostals", "Diaphragm", "Scalene muscles"], correctIndex: 2, explanation: "The diaphragm performs approximately 70–80% of the work of quiet inspiration by contracting and descending, increasing thoracic volume and creating negative intrathoracic pressure.", difficulty: "easy" },
  { topicId: 1, text: "The functional unit of gas exchange in the lung is the:", options: ["Bronchiole", "Alveolus", "Acinus", "Lobule"], correctIndex: 2, explanation: "The acinus (or primary lobule) is the gas-exchanging unit, comprising the respiratory bronchioles, alveolar ducts, alveolar sacs, and alveoli distal to a terminal bronchiole.", difficulty: "medium" },
  { topicId: 1, text: "The normal anatomic dead space in a healthy adult is approximately:", options: ["50 mL", "150 mL", "350 mL", "500 mL"], correctIndex: 1, explanation: "Anatomic dead space is approximately 1 mL/lb (2.2 mL/kg) IBW, or roughly 150 mL in a 70-kg adult. It represents the volume of the conducting airways (mouth to terminal bronchioles) that does not participate in gas exchange.", difficulty: "easy" },
  { topicId: 1, text: "Hypoxic pulmonary vasoconstriction (HPV) is a protective reflex that:", options: ["Dilates pulmonary vessels in hypoxic regions to increase blood flow", "Constricts pulmonary vessels in hypoxic regions to divert blood to better-ventilated areas", "Increases FRC", "Reduces airway resistance"], correctIndex: 1, explanation: "HPV constricts pulmonary vessels in poorly ventilated (hypoxic) alveolar regions, diverting blood flow to better-oxygenated areas, reducing intrapulmonary shunt and optimizing V/Q matching.", difficulty: "medium" },
  { topicId: 1, text: "The 'oxygen-hemoglobin dissociation curve' shifts to the RIGHT (reduced O2 affinity) with:", options: ["Decreased temperature, decreased 2,3-DPG, alkalosis", "Increased temperature, increased 2,3-DPG, acidosis, increased PaCO2", "Increased pH, decreased CO2", "Hypothermia and carboxyhemoglobin"], correctIndex: 1, explanation: "A rightward shift (Bohr effect) means hemoglobin releases O2 more readily — caused by increased temperature, increased 2,3-DPG, acidosis (decreased pH), and hypercapnia. This occurs in metabolically active tissues.", difficulty: "medium" },
  { topicId: 1, text: "The V/Q ratio at the apex of the lung compared to the base (in an upright person) is:", options: ["Lower at the apex", "Higher at the apex", "Equal throughout", "Higher at the base"], correctIndex: 1, explanation: "In upright position, both ventilation and perfusion are greater at the base, but perfusion increases more than ventilation. The apex has relatively more ventilation than perfusion — higher V/Q (~3.3 vs ~0.6 at the base).", difficulty: "medium" },
  { topicId: 1, text: "Which component of the respiratory control system is most sensitive to changes in PaCO2?", options: ["Peripheral chemoreceptors (carotid bodies)", "Central chemoreceptors in the medulla", "Hering-Breuer stretch receptors", "J-receptors (juxtacapillary)"], correctIndex: 1, explanation: "Central chemoreceptors in the medulla oblongata respond to changes in cerebrospinal fluid pH (driven by CO2). They are the primary regulators of resting ventilation and are exquisitely sensitive to PaCO2 changes.", difficulty: "medium" },
  { topicId: 1, text: "The apneustic center in the pons influences breathing by:", options: ["Initiating expiration", "Prolonging inspiration (apneustic breathing if unchecked)", "Increasing respiratory rate", "Responding to hypoxia"], correctIndex: 1, explanation: "The apneustic center in the lower pons promotes sustained inspiration. It is normally inhibited by the pneumotaxic center (upper pons) and vagal input. Damage to the pneumotaxic center causes prolonged gasping inspirations (apneustic breathing).", difficulty: "hard" },
  { topicId: 1, text: "Total lung capacity (TLC) minus residual volume (RV) equals:", options: ["Tidal volume (TV)", "Vital capacity (VC)", "Inspiratory capacity (IC)", "Functional residual capacity (FRC)"], correctIndex: 1, explanation: "VC = TLC − RV. Vital capacity is the maximal volume exhaled after a maximal inhalation — all the gas that can be moved in and out of the lungs.", difficulty: "easy" },
  { topicId: 1, text: "Which lung volume CANNOT be measured by spirometry alone and requires helium dilution or body plethysmography?", options: ["Tidal volume", "Inspiratory reserve volume", "Residual volume", "Inspiratory capacity"], correctIndex: 2, explanation: "Residual volume (RV) — the gas remaining after maximal exhalation — cannot be expelled and therefore cannot be measured by spirometry. It requires gas dilution techniques or body plethysmography.", difficulty: "medium" },
  { topicId: 1, text: "Type I pneumocytes (squamous alveolar cells) primarily function to:", options: ["Produce surfactant", "Form the thin gas-exchange membrane across which O2 and CO2 diffuse", "Phagocytose debris", "Repair alveolar damage"], correctIndex: 1, explanation: "Type I pneumocytes are flat, thin cells covering ~95% of the alveolar surface. Their thinness (0.2 μm) minimizes diffusion distance for gas exchange across the alveolar-capillary membrane.", difficulty: "medium" },
  { topicId: 1, text: "The alveolar air equation approximates PaO2 as:", options: ["PiO2 × FiO2", "PiO2 − (PaCO2 / RQ)", "FiO2 × (Pb − PH2O) − PaCO2/0.8", "PaO2 = PiO2 + PaCO2"], correctIndex: 2, explanation: "PAO2 = FiO2 × (Pb − 47) − PaCO2/RQ. At sea level with FiO2 0.21: PAO2 ≈ 0.21 × (760−47) − 40/0.8 = 150 − 50 = 100 mmHg. This is used to calculate the A-a gradient.", difficulty: "hard" },
  { topicId: 1, text: "Normal alveolar-arterial (A-a) oxygen gradient in a young healthy adult breathing room air is approximately:", options: ["0–5 mmHg", "5–15 mmHg", "20–30 mmHg", "40–50 mmHg"], correctIndex: 1, explanation: "The normal A-a gradient is 5–15 mmHg in young adults, increasing with age (approximate normal = age/4 + 4 mmHg). An elevated A-a gradient indicates a V/Q mismatch, shunt, or diffusion impairment.", difficulty: "medium" },
  { topicId: 1, text: "Carbon dioxide is transported in the blood primarily as:", options: ["Dissolved CO2 (PaCO2)", "Carbaminohemoglobin", "Bicarbonate (HCO3−)", "Carboxyhemoglobin"], correctIndex: 2, explanation: "~70% of CO2 is transported as bicarbonate (via carbonic anhydrase: CO2 + H2O → H2CO3 → H+ + HCO3−). About 23% as carbaminohemoglobin and 7% dissolved.", difficulty: "easy" },
  { topicId: 1, text: "The Haldane effect describes:", options: ["Rightward shift of the O2-Hgb curve with acidosis", "Deoxygenated hemoglobin's greater ability to carry CO2", "The effect of temperature on gas solubility", "CO2 stimulation of central chemoreceptors"], correctIndex: 1, explanation: "The Haldane effect: deoxygenated hemoglobin binds CO2 more avidly than oxygenated hemoglobin. In the tissues, hemoglobin gives up O2, increasing its CO2-carrying capacity — facilitating CO2 transport to the lungs.", difficulty: "hard" },
  { topicId: 1, text: "Which structure prevents food from entering the trachea during swallowing?", options: ["Vocal cords", "Epiglottis", "Uvula", "Cricoid cartilage"], correctIndex: 1, explanation: "The epiglottis is a leaf-shaped cartilage that folds downward over the glottis during swallowing, directing food into the esophagus. Its dysfunction (e.g., in neurological disorders) increases aspiration risk.", difficulty: "easy" },
  { topicId: 1, text: "Compliance of the respiratory system (Crs) is the combined compliance of:", options: ["Lungs and airways only", "Lungs and chest wall", "Diaphragm and chest wall", "Pleura and airways"], correctIndex: 1, explanation: "Total respiratory system compliance (Crs) combines lung compliance (CL) and chest wall compliance (Ccw) in series: 1/Crs = 1/CL + 1/Ccw. Normal Crs ≈ 100 mL/cmH₂O.", difficulty: "medium" },
  { topicId: 1, text: "The pores of Kohn are:", options: ["Openings between alveoli allowing collateral ventilation", "Connections between bronchioles and alveoli", "Pores in the pleural membrane", "Intercellular junctions in the alveolar wall"], correctIndex: 0, explanation: "Pores of Kohn are small openings (3–13 μm) in the alveolar walls connecting adjacent alveoli. They allow collateral ventilation — gas redistribution between alveoli that share a common alveolar wall, helping prevent atelectasis.", difficulty: "hard" },

  // ── TOPIC 2: Pulmonary Function Testing ──────────────────────────────────
  { topicId: 2, text: "FEV1/FVC ratio below what value defines obstructive lung disease?", options: ["0.90", "0.80", "0.70", "0.60"], correctIndex: 2, explanation: "An FEV1/FVC ratio < 0.70 (post-bronchodilator) defines airflow obstruction per GOLD and ATS/ERS guidelines. This criterion applies to adults; age-adjusted lower limits of normal (LLN) are also used.", difficulty: "easy" },
  { topicId: 2, text: "In restrictive lung disease, which of the following spirometry patterns is expected?", options: ["Decreased FEV1/FVC ratio with decreased TLC", "Normal or increased FEV1/FVC ratio with decreased TLC", "Increased RV with normal TLC", "Decreased FEV1 with normal FVC"], correctIndex: 1, explanation: "Restrictive disease reduces lung volumes (decreased TLC, FVC) but preserves the FEV1/FVC ratio (often ≥ 0.70). Both FEV1 and FVC decrease proportionally.", difficulty: "medium" },
  { topicId: 2, text: "DLCO (diffusing capacity for carbon monoxide) is decreased in all EXCEPT:", options: ["Emphysema", "Pulmonary fibrosis", "Pulmonary embolism", "Asthma (uncomplicated)"], correctIndex: 3, explanation: "DLCO is decreased in emphysema (loss of alveolar surface area), fibrosis (thickened membrane), and PE (reduced perfusion). Uncomplicated asthma typically has normal or even elevated DLCO.", difficulty: "medium" },
  { topicId: 2, text: "A patient with FVC 65% predicted, FEV1 63% predicted, FEV1/FVC 0.75 has:", options: ["Obstruction", "Restriction", "Mixed obstructive-restrictive", "Normal spirometry"], correctIndex: 1, explanation: "FEV1/FVC ≥ 0.70 rules out obstruction. Reduced FVC (65% predicted) with a preserved ratio indicates restriction. TLC measurement is needed to confirm restriction.", difficulty: "medium" },
  { topicId: 2, text: "Bronchodilator responsiveness is defined as an improvement of at least:", options: ["5% and 100 mL in FEV1 or FVC post-bronchodilator", "12% and 200 mL in FEV1 or FVC post-bronchodilator", "20% in FEV1 only", "10% in PEFR only"], correctIndex: 1, explanation: "ATS/ERS criteria: significant bronchodilator response = ≥ 12% AND ≥ 200 mL increase in FEV1 or FVC after inhaled bronchodilator (salbutamol 400 mcg). This suggests reversible airflow obstruction (asthma or COPD with reversibility).", difficulty: "medium" },
  { topicId: 2, text: "Peak expiratory flow (PEF) monitoring in asthma is used to:", options: ["Diagnose obstruction", "Monitor disease control and detect early deterioration at home", "Replace spirometry in all settings", "Measure lung volumes"], correctIndex: 1, explanation: "PEF monitoring is a simple, inexpensive tool for self-monitoring asthma control. A PEF < 80% of personal best or predicted, or diurnal variability > 20%, indicates poor control or impending exacerbation.", difficulty: "easy" },
  { topicId: 2, text: "On a flow-volume loop, a fixed upper airway obstruction (e.g., tracheal stenosis) produces:", options: ["Scooped-out expiratory limb", "Variable flattening of inspiratory limb only", "Flattening of both inspiratory and expiratory limbs", "Normal loop with reduced volume"], correctIndex: 2, explanation: "Fixed upper airway obstruction (e.g., tracheal stenosis with a rigid lesion) causes plateauing of both inspiratory and expiratory limbs of the flow-volume loop because flow is limited throughout the breath cycle.", difficulty: "hard" },
  { topicId: 2, text: "Functional residual capacity (FRC) is the sum of:", options: ["TV + IRV", "ERV + RV", "VC + RV", "IC + ERV"], correctIndex: 1, explanation: "FRC = ERV + RV. It is the volume of gas remaining in the lungs at the end of a normal passive exhalation — the equilibrium point between lung elastic recoil (inward) and chest wall recoil (outward).", difficulty: "easy" },
  { topicId: 2, text: "In COPD, residual volume (RV) is typically:", options: ["Decreased", "Normal", "Increased (air trapping)", "Absent"], correctIndex: 2, explanation: "In COPD, destruction of lung parenchyma and loss of elastic recoil lead to premature airway closure during exhalation, trapping gas and increasing RV. This hyperinflation increases TLC and FRC as well.", difficulty: "easy" },
  { topicId: 2, text: "The normal FEV1/FVC ratio in a healthy young adult is approximately:", options: ["0.50–0.60", "0.70–0.80", "0.75–0.85", "0.90–1.00"], correctIndex: 2, explanation: "In healthy young adults, the FEV1/FVC ratio is 0.75–0.85 (75–85%). This declines slightly with normal aging. Values below 0.70 are diagnostic of airflow obstruction.", difficulty: "easy" },
  { topicId: 2, text: "Which pattern on the flow-volume loop is characteristic of emphysema?", options: ["Fixed plateau on both limbs", "Scooped-out (concave) expiratory limb with normal peak flow", "Tall narrow loop with high peak flow", "Flattened inspiratory limb only"], correctIndex: 1, explanation: "Emphysema shows a scooped-out (concave upward) expiratory limb due to dynamic airway collapse — peak flow may be normal or reduced, but mid and late expiratory flow is severely reduced.", difficulty: "medium" },
  { topicId: 2, text: "MVV (maximum voluntary ventilation) is decreased in both obstructive and restrictive disease. In obstruction, the primary limiting factor is:", options: ["Respiratory muscle weakness", "Airway resistance limiting flow", "Reduced lung compliance", "Reduced chest wall compliance"], correctIndex: 1, explanation: "In obstruction, MVV is limited by increased airway resistance — air cannot move in and out fast enough. In restriction, MVV is limited by reduced lung volumes. Normal MVV ≈ FEV1 × 40.", difficulty: "medium" },
  { topicId: 2, text: "Pre- and post-bronchodilator spirometry is required to diagnose COPD because:", options: ["Post-BD results are always normal in COPD", "COPD is defined by post-BD FEV1/FVC < 0.70 to ensure obstruction is not fully reversible", "Pre-BD results are not reproducible", "Post-BD spirometry measures TLC"], correctIndex: 1, explanation: "COPD is defined by post-bronchodilator FEV1/FVC < 0.70, distinguishing it from asthma (where obstruction may be fully reversible). Post-BD testing ensures the obstruction is not completely reversible.", difficulty: "medium" },
  { topicId: 2, text: "Inspiratory capacity (IC) is equal to:", options: ["TLC − FRC", "FRC − RV", "TV + ERV", "VC − ERV"], correctIndex: 0, explanation: "IC = TLC − FRC. It is also equal to TV + IRV — the maximum volume inhaled from FRC. IC reduction in COPD (due to increased FRC from hyperinflation) correlates with exercise intolerance.", difficulty: "medium" },
  { topicId: 2, text: "The nitrogen washout test (single-breath or multi-breath) measures:", options: ["FEV1 and FVC", "Lung volumes (FRC/RV) and distribution of ventilation (evenness)", "Diffusing capacity (DLCO)", "Airway responsiveness (bronchoprovocation)"], correctIndex: 1, explanation: "Nitrogen washout tests measure FRC (by dilution) and assess the evenness of ventilation distribution. An uneven washout (elevated LCI — lung clearance index) indicates inhomogeneous ventilation, early in small airway disease.", difficulty: "hard" },
  { topicId: 2, text: "In a patient with neuromuscular disease, the PFT pattern shows FVC 45% predicted, normal FEV1/FVC ratio, normal TLC on plethysmography, reduced MIP and MEP. This suggests:", options: ["Intrinsic restrictive lung disease", "Respiratory muscle weakness (extrapulmonary restriction)", "Obstructive lung disease", "Upper airway obstruction"], correctIndex: 1, explanation: "Reduced MIP (inspiratory muscle strength) and MEP (expiratory muscle strength) with low FVC but normal FEV1/FVC and relatively preserved TLC indicates extrapulmonary restriction from respiratory muscle weakness.", difficulty: "hard" },
  { topicId: 2, text: "GOLD staging of COPD is based on:", options: ["Symptoms and exacerbation history only", "Post-bronchodilator FEV1 % predicted in patients with FEV1/FVC < 0.70", "FVC % predicted", "DLCO % predicted"], correctIndex: 1, explanation: "GOLD spirometric grades (1–4) are based on post-BD FEV1 % predicted: Grade 1 ≥ 80%, Grade 2 50–79%, Grade 3 30–49%, Grade 4 < 30%. Combined GOLD Assessment also incorporates symptoms (mMRC/CAT) and exacerbation history.", difficulty: "medium" },
  { topicId: 2, text: "Methacholine challenge (bronchoprovocation) test is used to:", options: ["Confirm COPD", "Diagnose airway hyperresponsiveness — positive if PC20 ≤ 8 mg/mL (strong evidence for asthma)", "Measure DLCO", "Assess bronchodilator reversibility"], correctIndex: 1, explanation: "Methacholine causes bronchoconstriction. A 20% fall in FEV1 at ≤ 8 mg/mL methacholine (PC20) is positive for airway hyperresponsiveness, strongly suggesting asthma. Normal PC20 > 16 mg/mL.", difficulty: "hard" },
  { topicId: 2, text: "In a normal flow-volume loop, expiratory flow is effort-dependent in the first portion and then becomes:", options: ["Effort-dependent throughout", "Effort-independent (flow-limited) at low lung volumes", "Zero at mid-lung volume", "Equal to inspiratory flow"], correctIndex: 1, explanation: "At high lung volumes, expiratory flow is effort-dependent (more effort = more flow). At lower lung volumes, dynamic compression causes flow limitation regardless of effort — the flow-volume loop reproduces reliably in healthy subjects.", difficulty: "hard" },
  { topicId: 2, text: "The 6-minute walk test (6MWT) in COPD primarily measures:", options: ["FEV1 reproducibility", "Functional exercise capacity and oxygen desaturation with activity", "DLCO", "Airway resistance"], correctIndex: 1, explanation: "The 6MWT measures how far a patient can walk in 6 minutes, assessing functional exercise capacity. Distance < 350 m predicts poor prognosis. SpO2 monitoring during 6MWT identifies exertional desaturation.", difficulty: "easy" },
  { topicId: 2, text: "Which measurement best differentiates intrathoracic from extrathoracic variable upper airway obstruction on flow-volume loops?", options: ["FEV1/FVC ratio", "Flattening pattern: expiratory (intrathoracic) vs. inspiratory (extrathoracic)", "TLC measurement", "Bronchodilator response"], correctIndex: 1, explanation: "Variable intrathoracic obstruction (e.g., tracheomalacia) flattens the expiratory limb (worsened by increased intrathoracic pressure during exhalation). Variable extrathoracic obstruction (e.g., vocal cord paralysis) flattens the inspiratory limb (worsened by negative pressure during inhalation).", difficulty: "hard" },
  { topicId: 2, text: "A patient reports dyspnea on exertion. Spirometry and lung volumes are normal. DLCO is markedly reduced. What is the most likely diagnosis?", options: ["Asthma", "Emphysema", "Pulmonary vascular disease (e.g., pulmonary hypertension or PE)", "Respiratory muscle weakness"], correctIndex: 2, explanation: "Isolated reduced DLCO with normal spirometry and lung volumes suggests pulmonary vascular disease — reduced pulmonary capillary blood volume limits CO uptake. Consider pulmonary hypertension or recurrent pulmonary emboli.", difficulty: "hard" },

  // ── TOPIC 3: ABG Analysis ────────────────────────────────────────────────
  { topicId: 3, text: "Normal arterial blood gas values are: pH 7.35–7.45, PaCO2 35–45 mmHg, HCO3 22–26 mEq/L, PaO2 80–100 mmHg. A pH of 7.30 with PaCO2 55 and HCO3 26 represents:", options: ["Metabolic acidosis", "Acute respiratory acidosis", "Metabolic alkalosis with respiratory compensation", "Compensated respiratory acidosis"], correctIndex: 1, explanation: "pH 7.30 (acidic), PaCO2 55 (high — respiratory cause), HCO3 26 (normal — no metabolic compensation yet). This is acute respiratory acidosis. Renal compensation would raise HCO3 over 2–3 days.", difficulty: "easy" },
  { topicId: 3, text: "A patient with diabetic ketoacidosis has pH 7.18, PaCO2 22, HCO3 8. This is:", options: ["Respiratory alkalosis", "Metabolic acidosis with respiratory compensation (Kussmaul breathing)", "Mixed metabolic and respiratory acidosis", "Respiratory acidosis with metabolic compensation"], correctIndex: 1, explanation: "pH 7.18 (acidic), HCO3 8 (low — metabolic cause), PaCO2 22 (low — appropriate respiratory compensation for metabolic acidosis). Kussmaul breathing (deep rapid breaths) blows off CO2 to partially compensate.", difficulty: "medium" },
  { topicId: 3, text: "Expected respiratory compensation for metabolic acidosis: for every 1 mEq/L decrease in HCO3, PaCO2 should decrease by approximately:", options: ["0.5 mmHg", "1.2 mmHg (Winter's formula)", "2 mmHg", "3 mmHg"], correctIndex: 1, explanation: "Winter's formula: expected PaCO2 = 1.5 × HCO3 + 8 ± 2. Alternatively, PaCO2 decreases by ~1.2 mmHg per 1 mEq/L drop in HCO3. If actual PaCO2 is higher than expected, there is a concurrent respiratory acidosis.", difficulty: "hard" },
  { topicId: 3, text: "In chronic respiratory acidosis (e.g., COPD), the expected renal compensation is:", options: ["Increased HCO3 retention — HCO3 rises 3.5 mEq/L per 10 mmHg rise in PaCO2", "Decreased HCO3", "Increased Cl− retention", "No compensation — pH remains low"], correctIndex: 0, explanation: "Chronic renal compensation for respiratory acidosis: HCO3 increases by 3.5 mEq/L per 10 mmHg rise in PaCO2 (acute is 1 mEq/L per 10 mmHg). This takes 3–5 days for complete compensation.", difficulty: "hard" },
  { topicId: 3, text: "A patient with pyloric stenosis (vomiting HCl) has pH 7.55, PaCO2 48, HCO3 40. This is:", options: ["Respiratory alkalosis", "Metabolic alkalosis with appropriate respiratory compensation", "Acute respiratory acidosis", "Mixed alkalosis"], correctIndex: 1, explanation: "pH 7.55 (alkaline), HCO3 40 (high — metabolic cause — HCl loss), PaCO2 48 (high — respiratory compensation, hypoventilation). Loss of gastric acid causes hypochloremic metabolic alkalosis.", difficulty: "medium" },
  { topicId: 3, text: "PaO2/FiO2 ratio (P/F ratio) of 250 on FiO2 0.50 indicates:", options: ["Normal oxygenation", "Mild hypoxemia, no ARDS criteria", "Moderate ARDS (P/F 100–200)", "Severe ARDS (P/F < 100)"], correctIndex: 1, explanation: "P/F = PaO2 / FiO2 = 125/0.50 = 250. Berlin ARDS criteria: Mild P/F 200–300. Wait — P/F = PaO2/FiO2. If P/F ratio is 250, that's in the mild ARDS range (200–300). Normal P/F ≈ 400–500.", difficulty: "medium" },
  { topicId: 3, text: "Carboxyhemoglobin (COHb) elevation causes pulse oximetry to:", options: ["Read falsely LOW", "Read falsely HIGH (near 100%)", "Read accurately", "Fluctuate rapidly"], correctIndex: 1, explanation: "Standard pulse oximetry cannot distinguish oxyhemoglobin from carboxyhemoglobin — both absorb light similarly. In CO poisoning, SpO2 reads near 100% despite severe tissue hypoxia. CO-oximetry (ABG co-oximeter) is required.", difficulty: "medium" },
  { topicId: 3, text: "Methemoglobin causes pulse oximetry to drift toward:", options: ["100%", "0%", "85% regardless of true SaO2", "The true SaO2 value"], correctIndex: 2, explanation: "Methemoglobin absorbs equally at both SpO2 wavelengths, driving the reading toward 85%. If true SaO2 is above 85%, SpO2 reads falsely low; if below 85%, it reads falsely high.", difficulty: "hard" },
  { topicId: 3, text: "A patient has pH 7.40, PaCO2 40, HCO3 25, PaO2 55 on room air. SpO2 is 87%. The primary problem is:", options: ["Respiratory acidosis", "Metabolic acidosis", "Hypoxemia without acid-base disturbance", "Metabolic alkalosis"], correctIndex: 2, explanation: "Normal pH, PaCO2, and HCO3 — no acid-base disorder. PaO2 55 mmHg (normal ≥ 80) with SpO2 87% indicates significant hypoxemia. Supplemental oxygen is needed immediately.", difficulty: "easy" },
  { topicId: 3, text: "The anion gap is calculated as:", options: ["HCO3 − Cl−", "Na+ − (Cl− + HCO3−)", "Na+ + K+ − Cl−", "HCO3 + Cl−"], correctIndex: 1, explanation: "Anion gap = Na+ − (Cl− + HCO3−). Normal is 8–12 mEq/L. An elevated AG (> 12) indicates unmeasured anions (e.g., lactate, ketones, uremia, toxins — 'MUDPILES'). Normal AG metabolic acidosis = hyperchloremic acidosis (e.g., diarrhea, RTA).", difficulty: "medium" },
  { topicId: 3, text: "For a patient with pH 7.25, PaCO2 60, HCO3 26 on controlled ventilation, what change will most rapidly improve pH?", options: ["Give sodium bicarbonate IV", "Increase respiratory rate to decrease PaCO2", "Increase FiO2", "Increase PEEP"], correctIndex: 1, explanation: "The pH is low due to respiratory acidosis (high PaCO2). Increasing the respiratory rate increases minute ventilation, removing CO2 and rapidly correcting respiratory acidosis. Bicarbonate is only useful for metabolic acidosis.", difficulty: "medium" },
  { topicId: 3, text: "A COPD patient with chronic hypercapnia (baseline PaCO2 60, HCO3 38) acutely presents with pH 7.30. The acute change in PaCO2 from baseline is most consistent with:", options: ["Only metabolic acidosis", "Acute-on-chronic respiratory acidosis (new rise in PaCO2 on top of chronic)", "New respiratory alkalosis", "Pure metabolic alkalosis"], correctIndex: 1, explanation: "This patient has chronic compensation (HCO3 38 for PaCO2 60). pH 7.30 with presumably higher PaCO2 now represents an acute exacerbation — more CO2 is being retained on top of the chronic baseline. This is acute-on-chronic respiratory acidosis.", difficulty: "hard" },
  { topicId: 3, text: "Oxygen saturation (SaO2) of 90% corresponds to approximately what PaO2?", options: ["50 mmHg", "60 mmHg", "70 mmHg", "80 mmHg"], correctIndex: 1, explanation: "On the oxyhemoglobin dissociation curve, SaO2 90% corresponds to PaO2 ~60 mmHg — the 'shoulder' of the curve. Below this point, small drops in PaO2 cause large drops in SaO2.", difficulty: "easy" },
  { topicId: 3, text: "What characterizes type II respiratory failure (ventilatory failure)?", options: ["Low PaO2 only", "Low PaO2 with elevated PaCO2 (hypercapnic hypoxemia)", "Normal PaO2 with high PaCO2", "Elevated PaO2 and PaCO2"], correctIndex: 1, explanation: "Type II respiratory failure: PaO2 < 60 mmHg AND PaCO2 > 45 mmHg. This indicates ventilatory failure — the lungs cannot maintain CO2 elimination. Causes include COPD, NMD, chest wall disease, obesity hypoventilation.", difficulty: "medium" },
  { topicId: 3, text: "In pure metabolic alkalosis, the expected respiratory compensation (hypoventilation) is approximately:", options: ["PaCO2 rises 0.5 mmHg per 1 mEq/L rise in HCO3", "PaCO2 rises 0.7 mmHg per 1 mEq/L rise in HCO3", "No respiratory compensation occurs", "PaCO2 falls 1.2 mmHg per 1 mEq/L rise in HCO3"], correctIndex: 1, explanation: "Expected compensation for metabolic alkalosis: PaCO2 rises by 0.7 mmHg per 1 mEq/L increase in HCO3 (Winters formula for alkalosis: expected PaCO2 = 0.7 × HCO3 + 21 ± 2).", difficulty: "hard" },
  { topicId: 3, text: "A patient is found to have pH 7.38, PaCO2 70, HCO3 42. This ABG represents:", options: ["Uncompensated respiratory acidosis", "Acute respiratory alkalosis", "Fully compensated chronic respiratory acidosis", "Mixed metabolic and respiratory alkalosis"], correctIndex: 2, explanation: "pH 7.38 (normal), PaCO2 70 (high), HCO3 42 (very high — renal compensation). Fully compensated chronic respiratory acidosis — classic COPD ABG. Renal HCO3 retention normalizes pH.", difficulty: "medium" },
  { topicId: 3, text: "The P(A-a)O2 gradient is increased in all of the following EXCEPT:", options: ["V/Q mismatch", "Intrapulmonary shunt", "Diffusion impairment", "Hypoventilation with normal lungs"], correctIndex: 3, explanation: "Hypoventilation alone (e.g., respiratory center depression) causes hypoxemia by lowering PAO2 equally — PaO2 falls but the A-a gradient remains normal. All other causes (shunt, V/Q mismatch, diffusion block) widen the A-a gradient.", difficulty: "hard" },
  { topicId: 3, text: "Which change to the ABG would indicate adequate reversal of opioid-induced respiratory depression after naloxone administration?", options: ["HCO3 decreases", "PaCO2 decreases and pH returns toward normal", "PaO2 decreases", "A-a gradient increases"], correctIndex: 1, explanation: "Opioid overdose causes respiratory depression → CO2 retention (rising PaCO2) → respiratory acidosis. Successful reversal restores ventilatory drive: PaCO2 decreases and pH rises toward normal.", difficulty: "medium" },
  { topicId: 3, text: "A pH of 7.52 with PaCO2 28 and HCO3 23 represents:", options: ["Metabolic alkalosis", "Acute respiratory alkalosis (hyperventilation)", "Mixed alkalosis", "Compensated metabolic alkalosis"], correctIndex: 1, explanation: "pH 7.52 (alkaline), PaCO2 28 (low — respiratory cause), HCO3 23 (normal — no metabolic compensation). Acute respiratory alkalosis from hyperventilation. Causes include anxiety, pain, PE, sepsis, pregnancy.", difficulty: "easy" },
  { topicId: 3, text: "In a ventilated patient, a sudden rise in PaCO2 from 40 to 65 with unchanged settings most likely indicates:", options: ["Increased CO2 production (fever, shivering)", "Decreased minute ventilation from a circuit leak", "Decreased metabolic rate", "Increased oxygen consumption only"], correctIndex: 1, explanation: "Circuit leak reduces delivered tidal volume and hence minute ventilation → CO2 accumulates. Increased CO2 production (fever, sepsis, nutrition) can also raise PaCO2, but a sudden rise suggests a ventilatory cause (leak, obstruction).", difficulty: "medium" },
  { topicId: 3, text: "The SaO2/SpO2 relationship becomes unreliable below what SpO2?", options: ["98%", "92%", "88%", "80%"], correctIndex: 1, explanation: "Pulse oximetry is accurate (±2%) when SpO2 is 70–100%. Below 92% (on the steep part of the dissociation curve), small errors in light absorption cause larger errors in calculated SaO2.", difficulty: "medium" },
  { topicId: 3, text: "Elevated lactate on ABG (lactic acidosis) with high anion gap most commonly represents:", options: ["Respiratory acidosis", "Type A lactic acidosis — tissue hypoperfusion/hypoxia (shock, cardiac arrest)", "Type B — medications, liver disease", "Metabolic alkalosis"], correctIndex: 1, explanation: "Type A lactic acidosis results from tissue hypoperfusion/hypoxia (septic shock, cardiac arrest, severe hypoxemia). Anaerobic metabolism generates excess lactate. It indicates high acuity and poor prognosis.", difficulty: "medium" },

  // ── TOPIC 5: Airway Management ───────────────────────────────────────────
  { topicId: 5, text: "The correct ETT size for an average adult male is:", options: ["6.0–6.5 mm internal diameter", "7.0–8.0 mm internal diameter", "8.5–9.0 mm internal diameter", "5.0–5.5 mm internal diameter"], correctIndex: 1, explanation: "Adult male: 7.5–8.0 mm ID ETT. Adult female: 7.0–7.5 mm. Larger tubes facilitate suctioning and reduce airway resistance; tubes that are too large risk subglottic trauma.", difficulty: "easy" },
  { topicId: 5, text: "Correct ETT depth (at the lips) for an average adult is approximately:", options: ["15–17 cm", "20–23 cm for males, 19–21 cm for females", "25–28 cm", "12–14 cm"], correctIndex: 1, explanation: "Standard ETT depth at the teeth: ~23 cm for males, ~21 cm for females. The tip should be 3–5 cm above the carina. Confirm by auscultation, end-tidal CO2, and chest X-ray (tip at T2–T4).", difficulty: "easy" },
  { topicId: 5, text: "Gold standard confirmation of ETT placement in the trachea is:", options: ["Auscultation of bilateral breath sounds", "Chest rise with ventilation", "Continuous waveform capnography (EtCO2)", "Tube fogging"], correctIndex: 2, explanation: "Continuous waveform capnography is the gold standard for confirming and monitoring tracheal intubation. It detects CO2 in exhaled gas only from the lungs — esophageal intubation shows no CO2 waveform.", difficulty: "easy" },
  { topicId: 5, text: "Rapid sequence intubation (RSI) involves:", options: ["Gentle bag-mask ventilation followed by intubation", "Simultaneous administration of a sedative and neuromuscular blocking agent to achieve rapid intubation with minimal aspiration risk", "Intubation without any medications", "Topical anesthesia alone"], correctIndex: 1, explanation: "RSI: simultaneous induction agent (e.g., ketamine, propofol, etomidate) + rapid-onset NMB (succinylcholine or rocuronium) to achieve intubating conditions in ~60 seconds. Used in patients at high aspiration risk (full stomach).", difficulty: "easy" },
  { topicId: 5, text: "Succinylcholine is contraindicated in which patient?", options: ["Trauma patient with full stomach", "Burn patient >48–72 hours post-injury", "Pediatric patient for RSI", "Hemodynamically unstable patient"], correctIndex: 1, explanation: "After major burns, crush injuries, denervation injuries (48–72+ hours), succinylcholine causes massive hyperkalemia due to upregulation of extrajunctional acetylcholine receptors. Rocuronium (1.2 mg/kg) is the alternative.", difficulty: "hard" },
  { topicId: 5, text: "Sellick's maneuver (cricoid pressure) during RSI is intended to:", options: ["Open the glottis for better visualization", "Compress the esophagus to prevent passive regurgitation during induction", "Mark the cricothyroid membrane for emergency airway access", "Reduce the gag reflex"], correctIndex: 1, explanation: "Sellick's maneuver: firm downward pressure on the cricoid cartilage occludes the esophagus between the cricoid and vertebral body, theoretically preventing passive regurgitation. Its evidence is debated; it should be released if it impairs laryngoscopy.", difficulty: "medium" },
  { topicId: 5, text: "The 'LEMON' assessment for difficult airway predicts difficulty with direct laryngoscopy. LEMON stands for:", options: ["Larynx, Edema, Mouth, Opening, Neck", "Look externally, Evaluate 3-3-2 rule, Mallampati, Obstruction, Neck mobility", "Laryngospasm, Emesis, Mandible, Obesity, Nose", "Lesion, ETT, Mask, Oxygen, NMB"], correctIndex: 1, explanation: "LEMON: Look (external features — beard, obese neck), Evaluate 3-3-2 (mouth opening 3 fingers, hyoid-chin 3 fingers, hyoid-thyroid notch 2 fingers), Mallampati class, Obstruction/Obesity, Neck mobility.", difficulty: "medium" },
  { topicId: 5, text: "A laryngeal mask airway (LMA) is a:", options: ["Definitive airway that protects against aspiration", "Supraglottic airway device providing a seal over the larynx — does NOT protect against aspiration", "Nasopharyngeal airway", "Device placed below the vocal cords"], correctIndex: 1, explanation: "The LMA sits in the hypopharynx and forms a low-pressure seal over the larynx. It maintains a patent airway but does NOT protect against aspiration. Contraindicated in patients at high aspiration risk.", difficulty: "easy" },
  { topicId: 5, text: "Cricothyrotomy (surgical or needle) is indicated when:", options: ["Routine RSI is planned", "Cannot intubate, cannot oxygenate (CICO) scenario — failed airway", "Patient refuses intubation", "SpO2 is 92%"], correctIndex: 1, explanation: "Cricothyrotomy is the rescue technique in a 'cannot intubate, cannot oxygenate' (CICO) emergency — the final step in the difficult airway algorithm. The cricothyroid membrane is incised to establish an emergency airway.", difficulty: "medium" },
  { topicId: 5, text: "After orotracheal intubation, absent breath sounds on the LEFT and normal sounds on the RIGHT suggest:", options: ["Esophageal intubation", "Left pneumothorax", "Right main-stem intubation", "Bilateral bronchospasm"], correctIndex: 2, explanation: "Absent left breath sounds post-intubation indicates the ETT has advanced into the right main bronchus (more vertical angle). Pull the tube back 1–2 cm and reconfirm bilateral sounds. Confirm position by CXR.", difficulty: "easy" },
  { topicId: 5, text: "Tracheostomy compared to prolonged oral ETT intubation reduces:", options: ["Risk of aspiration pneumonia", "ICU and hospital length of stay and improves patient comfort", "Need for humidification", "FiO2 requirements"], correctIndex: 1, explanation: "Tracheostomy reduces airway resistance, improves oral hygiene, allows patients to eat and speak (with speaking valves), reduces sedation needs, and is associated with shorter ICU stays in patients requiring prolonged MV.", difficulty: "medium" },
  { topicId: 5, text: "The Mallampati classification assesses:", options: ["Degree of tracheal deviation", "Oropharyngeal visibility (tongue size relative to oral cavity) as a predictor of difficult intubation", "Neck circumference", "Degree of mouth opening"], correctIndex: 1, explanation: "Mallampati class (I–IV) grades the visibility of pharyngeal structures with the patient seated, mouth open, and tongue out. Class III–IV (only soft palate or hard palate visible) predicts difficult laryngoscopy.", difficulty: "medium" },
  { topicId: 5, text: "A cuffed ETT in pediatric patients (age > 2 years) is now preferred over uncuffed because:", options: ["Larger tube diameter improves gas exchange", "Cuffed tubes reduce the need for tube exchange if the leak is too large, with equal safety when pressures are controlled", "Uncuffed tubes are too large", "Cuffed tubes have smaller external diameters"], correctIndex: 1, explanation: "Modern data support cuffed ETTs in children > 2 years and in neonates for special indications (e.g., poor lung compliance). Cuffed tubes reduce the number of laryngoscopy passes (tube exchanges) when cuff pressure is monitored.", difficulty: "hard" },
  { topicId: 5, text: "The Cormack-Lehane grading system classifies:", options: ["Airway anatomy on imaging", "Laryngoscopic view — Grade 1 (full glottis visible) to Grade 4 (no glottic structures visible)", "Degree of subglottic stenosis", "Tracheal secretion viscosity"], correctIndex: 1, explanation: "Cormack-Lehane: Grade 1 = full glottis visible; Grade 2 = partial glottis or arytenoids; Grade 3 = epiglottis only; Grade 4 = no laryngeal structures. Grade 3–4 indicates difficult intubation.", difficulty: "medium" },
  { topicId: 5, text: "Video laryngoscopy compared to direct laryngoscopy:", options: ["Has no advantage in difficult airways", "Provides improved glottic visualization (better CL grade), especially in difficult airways and inexperienced operators", "Requires the same head positioning", "Cannot be used with RSI"], correctIndex: 1, explanation: "Video laryngoscopy (e.g., GlideScope, McGrath) provides indirect visualization via a camera at the blade tip, achieving better glottic views especially in difficult airways, C-spine precautions, and obese patients.", difficulty: "medium" },
  { topicId: 5, text: "Post-extubation stridor in an adult most commonly indicates:", options: ["Pneumothorax", "Subglottic edema from prolonged intubation — managed with nebulized racemic epinephrine and/or IV steroids", "Bronchospasm", "Tracheomalacia"], correctIndex: 1, explanation: "Post-extubation stridor (high-pitched inspiratory noise) is usually subglottic edema. Management: nebulized racemic epinephrine (vasoconstriction), IV dexamethasone (reduce inflammation), and heliox to decrease turbulent flow. Re-intubation if severe.", difficulty: "medium" },
  { topicId: 5, text: "A Passy-Muir speaking valve is placed on a tracheostomy tube to:", options: ["Seal the tracheostomy to prevent air escape", "Allow one-way airflow (in through trach, out through upper airway) restoring phonation and cough", "Provide PEEP during mechanical ventilation", "Replace the tracheostomy cuff"], correctIndex: 1, explanation: "The Passy-Muir valve is a one-way valve (open during inspiration, closed during expiration) that redirects expiratory airflow through the upper airway — restoring voice, improving swallowing, and enabling secretion clearance.", difficulty: "medium" },
  { topicId: 5, text: "Which finding most reliably confirms esophageal intubation?", options: ["Gurgling over the stomach", "Absent EtCO2 waveform on continuous capnography", "Low SpO2 immediately after intubation", "Absence of bilateral breath sounds"], correctIndex: 1, explanation: "Absent EtCO2 waveform on capnography is the most reliable indicator of esophageal intubation. SpO2 may remain high for minutes after esophageal intubation (pre-oxygenation). Always confirm with waveform capnography.", difficulty: "easy" },
  { topicId: 5, text: "Optimal head position for direct laryngoscopy (in patients without C-spine precaution) is:", options: ["Neutral/flat position", "Sniffing position (neck flexed, head extended — aligning oral, pharyngeal, laryngeal axes)", "Maximum neck flexion", "Lateral decubitus"], correctIndex: 1, explanation: "The sniffing position (neck slightly flexed on a pillow, head extended at the atlantooccipital joint) aligns the three laryngoscopy axes — oral, pharyngeal, and laryngeal — for best glottic visualization.", difficulty: "easy" },
  { topicId: 5, text: "Accidental decannulation (dislodgment) of a fresh tracheostomy (< 7 days old) is an emergency because:", options: ["Air will enter the vascular space", "The tract has not yet matured — the stoma may close, making re-cannulation difficult or impossible", "Cuff rupture is inevitable", "Orotracheal intubation becomes impossible"], correctIndex: 1, explanation: "A fresh tracheostomy tract (< 7 days) is not mature and may close rapidly upon decannulation. This is a life-threatening airway emergency. Do NOT attempt blind re-insertion — secure the airway from above (oral intubation) first.", difficulty: "hard" },
  { topicId: 5, text: "Which airway adjunct is most appropriate for an unconscious patient with no gag reflex who requires bag-mask ventilation?", options: ["Nasal cannula", "Oropharyngeal airway (OPA)", "Nasopharyngeal airway (NPA)", "Venturi mask"], correctIndex: 1, explanation: "An oropharyngeal airway (Guedel airway) maintains upper airway patency in an unconscious, gagged-less patient by displacing the tongue anteriorly. It should not be used in conscious patients (triggers gag/vomiting).", difficulty: "easy" },
  { topicId: 5, text: "Subglottic secretion drainage via specially designed ETTs (e.g., Hi-Lo Evac) reduces:", options: ["Auto-PEEP", "Ventilator-associated pneumonia (VAP) by preventing microaspiration of contaminated pooled secretions", "Tidal volume loss", "Oxygen requirements"], correctIndex: 1, explanation: "Subglottic secretion drainage ETTs have a dorsal lumen above the cuff for continuous or intermittent aspiration of pooled oropharyngeal secretions, preventing microaspiration — reducing VAP by 50%.", difficulty: "medium" },

  // ── TOPIC 6: Oxygen Therapy & Delivery Devices ──────────────────────────
  { topicId: 6, text: "A nasal cannula at 2 L/min delivers an approximate FiO2 of:", options: ["0.24", "0.28", "0.32", "0.44"], correctIndex: 1, explanation: "Nasal cannula: FiO2 increases ~0.04 per 1 L/min increase in flow. At 2 L/min: 0.21 + (2 × 0.04) = 0.29, approximately 0.28. Actual FiO2 varies with breathing pattern.", difficulty: "easy" },
  { topicId: 6, text: "The maximum reliable FiO2 achievable with a non-rebreather mask (NRB) is approximately:", options: ["0.50", "0.60", "0.70", "0.90–0.95"], correctIndex: 3, explanation: "A properly fitting NRB mask with tight seal and high flow (10–15 L/min to keep reservoir bag inflated) can deliver 0.90–0.95 FiO2. The one-way valves prevent exhaled gas from re-entering the reservoir.", difficulty: "easy" },
  { topicId: 6, text: "Venturi masks are preferred over nasal cannulas in COPD patients requiring supplemental O2 because:", options: ["They deliver higher FiO2", "They provide a precise, consistent FiO2 regardless of breathing pattern", "They are more comfortable", "They eliminate CO2 retention risk"], correctIndex: 1, explanation: "Venturi (air-entrainment) masks use fixed-size jets to entrain room air in precise proportions, delivering accurate FiO2 (24–50%). This prevents excessive oxygenation and CO2 retention in hypoxic-drive COPD patients.", difficulty: "medium" },
  { topicId: 6, text: "High-flow nasal cannula (HFNC, e.g., Optiflow) at 40 L/min generates an approximate PEEP of:", options: ["0–1 cmH₂O", "2–4 cmH₂O", "5–8 cmH₂O", "10–12 cmH₂O"], correctIndex: 1, explanation: "HFNC generates approximately 1 cmH₂O PEEP per 10 L/min of flow when the mouth is closed. At 40 L/min ≈ 3–4 cmH₂O. This modest PEEP, combined with dead space flushing and accurate FiO2, improves oxygenation.", difficulty: "medium" },
  { topicId: 6, text: "SpO2 target for most non-ARDS patients on supplemental oxygen should be:", options: ["≥ 99–100%", "95–98%", "88–92%", "80–85%"], correctIndex: 1, explanation: "For most patients, target SpO2 94–98% (or 92–96% for selected groups). Hyperoxia (SpO2 > 98–99%) is associated with worse outcomes in STEMI, stroke, and post-cardiac arrest patients — avoid unnecessary high FiO2.", difficulty: "medium" },
  { topicId: 6, text: "For COPD patients on supplemental oxygen, the target SpO2 is:", options: ["≥ 98%", "95–98%", "88–92%", "80–85%"], correctIndex: 2, explanation: "Target SpO2 88–92% in COPD to provide adequate oxygenation while avoiding suppression of the hypoxic respiratory drive and worsening hypercapnia. Higher SpO2 in COPD patients can lead to CO2 retention (Haldane effect + reduced HPV).", difficulty: "medium" },
  { topicId: 6, text: "Absorptive atelectasis from high FiO2 occurs because:", options: ["Oxygen causes bronchospasm", "Nitrogen (which normally splints alveoli open) is washed out, causing alveolar collapse when O2 is rapidly absorbed", "High FiO2 reduces surfactant production", "Oxygen increases mucus production"], correctIndex: 1, explanation: "At high FiO2, nitrogen is displaced from alveoli. Without nitrogen to 'splint' alveoli, the rapidly absorbed oxygen leaves alveoli prone to collapse (absorptive atelectasis) — especially in low V/Q units.", difficulty: "hard" },
  { topicId: 6, text: "The partial rebreather mask differs from the NRB mask in that:", options: ["It has no reservoir bag", "It lacks one-way valves, allowing some exhaled gas to mix with reservoir gas", "It delivers lower FiO2 than a simple face mask", "It is used only during CPR"], correctIndex: 1, explanation: "The partial rebreather mask has a reservoir bag but lacks the one-way valves of a NRB mask, so the first portion of exhaled gas (dead space gas, not CO2-rich) re-enters the bag. FiO2 achieved is lower (0.60–0.80) than a true NRB.", difficulty: "medium" },
  { topicId: 6, text: "Helium-oxygen therapy (Heliox) reduces work of breathing in upper airway obstruction primarily because:", options: ["Helium provides more oxygen per molecule", "Helium's low density reduces turbulent flow and airway resistance", "Heliox is a bronchodilator", "Helium increases surfactant production"], correctIndex: 1, explanation: "Helium is much less dense than nitrogen (0.164 vs. 1.25 g/L). In turbulent (high-resistance) airway obstruction, replacing nitrogen with helium reduces the Reynolds number, promoting laminar flow and reducing WOB.", difficulty: "medium" },
  { topicId: 6, text: "Oxygen toxicity from prolonged high FiO2 first manifests as:", options: ["Bronchospasm and wheezing", "Substernal chest pain, cough, and tracheobronchitis (first symptoms)", "Cyanosis", "Hypercapnia"], correctIndex: 1, explanation: "Early signs of oxygen toxicity (FiO2 > 0.50–0.60 for > 24–48 hrs): substernal burning pain worsened by deep inspiration, cough, and tracheobronchitis. Progressive exposure leads to interstitial edema, consolidation, and ARDS-like injury.", difficulty: "medium" },
  { topicId: 6, text: "Which of the following oxygen delivery devices requires the highest flow rate to maintain adequate FiO2?", options: ["Nasal cannula at 2 L/min", "Simple face mask (minimum 5 L/min to flush CO2)", "Venturi mask at 24% (3–4 L/min)", "Reservoir cannula"], correctIndex: 1, explanation: "Simple face masks require minimum 5–6 L/min to flush exhaled CO2 from the mask and prevent rebreathing. At lower flows, CO2 accumulates in the mask, reducing FiO2 and causing CO2 rebreathing.", difficulty: "medium" },
  { topicId: 6, text: "An oxygen concentrator works by:", options: ["Compressing liquid oxygen into gas phase", "Using a molecular sieve (zeolite) to adsorb nitrogen from room air, concentrating oxygen", "Electrolyzing water to produce oxygen", "Filtering carbon dioxide from room air"], correctIndex: 1, explanation: "Oxygen concentrators use zeolite molecular sieves that selectively adsorb nitrogen from compressed room air, releasing concentrated oxygen (90–95% FiO2) for home use. They require electricity and produce warm O2.", difficulty: "medium" },
  { topicId: 6, text: "HFNC is superior to conventional low-flow oxygen for hypoxemic respiratory failure primarily because:", options: ["HFNC delivers lower FiO2", "HFNC meets or exceeds patient's peak inspiratory flow demand, minimizing air entrainment and FiO2 dilution", "HFNC delivers less flow", "HFNC does not require humidification"], correctIndex: 1, explanation: "With HFNC delivering 30–60 L/min of fully conditioned gas at precise FiO2, it meets or exceeds the patient's peak inspiratory demand (15–30 L/min at rest), preventing room air entrainment that dilutes FiO2 with conventional devices.", difficulty: "medium" },
  { topicId: 6, text: "Retinopathy of prematurity (ROP) in premature neonates is associated with:", options: ["Hypoxia (SpO2 < 88%)", "Hyperoxia — excessive oxygen exposure causing retinal vascular damage", "Hypercapnia", "Anemia"], correctIndex: 1, explanation: "ROP occurs when excess oxygen causes retinal vessel constriction followed by abnormal proliferative neovascularization. Target SpO2 90–95% in premature neonates < 32 weeks gestational age to minimize ROP risk.", difficulty: "medium" },
  { topicId: 6, text: "The FiO2 delivered by a nasal cannula is inversely proportional to:", options: ["Flow rate setting", "Patient's peak inspiratory flow rate (higher flow rate → more room air entrained → lower FiO2)", "Oxygen source pressure", "Humidity level"], correctIndex: 1, explanation: "Cannulas and face masks are 'variable performance' devices — FiO2 depends on patient breathing pattern. A patient who breathes rapidly with large tidal volumes entrains more room air, diluting the delivered O2 and lowering actual FiO2.", difficulty: "hard" },
  { topicId: 6, text: "Chronic home oxygen therapy is indicated in COPD patients when:", options: ["PaO2 is 70 mmHg or SpO2 93% at rest", "Resting PaO2 ≤ 55 mmHg (or SpO2 ≤ 88%) or PaO2 56–59 with cor pulmonale or erythrocytosis", "Only during exercise", "FEV1 < 50% predicted"], correctIndex: 1, explanation: "Long-term O2 therapy indications (at rest): PaO2 ≤ 55 mmHg or SpO2 ≤ 88%. PaO2 56–59 with cor pulmonale (P pulmonale, edema) or Hct ≥ 55% also qualify. LTOT improves survival in COPD patients who meet these criteria.", difficulty: "medium" },
  { topicId: 6, text: "Oxygen humidification is generally NOT required at flow rates below:", options: ["1 L/min", "4 L/min", "8 L/min", "12 L/min"], correctIndex: 1, explanation: "AARTs guidelines: humidification not required for flows ≤ 4 L/min via nasal cannula. Above 4 L/min (especially with prolonged use), humidification reduces mucosal drying, discomfort, and epistaxis.", difficulty: "easy" },
  { topicId: 6, text: "A transtracheal oxygen catheter (TTOC) offers the advantage of:", options: ["Higher FiO2 at any given flow compared to nasal cannula", "Lower flow requirements, cosmetic advantages, and reservoir function in the trachea reducing dead space", "No need for cleaning", "Higher flow rates required"], correctIndex: 1, explanation: "TTOC delivers O2 directly into the trachea, bypassing dead space. The trachea acts as a reservoir. This allows therapeutic SpO2 at lower flow rates (30–50% less O2), reducing cost and improving compliance.", difficulty: "hard" },
  { topicId: 6, text: "An air-entrainment (jet) nebulizer operates on which principle?", options: ["Ultrasound vibration of the liquid", "Bernoulli effect — high-velocity gas past a jet creates a pressure drop that draws liquid up and shatters it into aerosol particles", "Electric heating of the solution", "Gravity-fed flow"], correctIndex: 1, explanation: "Jet (pneumatic) nebulizers use the Bernoulli principle: fast gas past a narrow jet creates a low-pressure zone that draws liquid from the reservoir up a capillary tube, where it is shattered into respirable particles by the gas stream.", difficulty: "medium" },
  { topicId: 6, text: "Which oxygen delivery device provides the LOWEST reliable FiO2 (used for mild hypoxemia only)?", options: ["Non-rebreather mask", "Partial rebreather mask", "Simple face mask", "Nasal cannula at 1 L/min (FiO2 ≈ 0.24)"], correctIndex: 3, explanation: "Nasal cannula at 1 L/min delivers approximately FiO2 0.24–0.25 — the lowest FiO2 reliably achievable with a standard delivery device. Appropriate for mild hypoxemia where minimal supplementation is needed.", difficulty: "easy" },

  // ── TOPIC 7: Respiratory Medications & Pharmacology ─────────────────────
  { topicId: 7, text: "Albuterol (salbutamol) works as a bronchodilator by:", options: ["Blocking muscarinic receptors on airway smooth muscle", "Stimulating beta-2 adrenergic receptors, increasing cAMP and causing smooth muscle relaxation", "Inhibiting leukotriene synthesis", "Blocking histamine H1 receptors"], correctIndex: 1, explanation: "Albuterol is a short-acting beta-2 agonist (SABA). Beta-2 receptor activation → adenylyl cyclase → increased cAMP → relaxation of airway smooth muscle and bronchodilation. Onset: 5–15 min; duration: 4–6 hours.", difficulty: "easy" },
  { topicId: 7, text: "Ipratropium bromide (Atrovent) bronchodilates via:", options: ["Beta-2 agonism", "Muscarinic receptor (M3) antagonism — blocks acetylcholine-induced bronchoconstriction", "Inhibition of mast cell degranulation", "Direct smooth muscle relaxation"], correctIndex: 1, explanation: "Ipratropium is a short-acting muscarinic antagonist (SAMA). It blocks acetylcholine at M3 receptors on airway smooth muscle, reducing bronchoconstriction — particularly effective in COPD and minimally in asthma.", difficulty: "easy" },
  { topicId: 7, text: "The combination inhaler Combivent/DuoNeb (ipratropium + albuterol) is used because:", options: ["Both drugs have the same mechanism", "Additive bronchodilation via two different pathways (beta-2 agonism + muscarinic antagonism)", "To reduce steroid dose requirements", "Both drugs are long-acting"], correctIndex: 1, explanation: "Ipratropium and albuterol bronchodilate via complementary mechanisms. Their combination provides additive bronchodilation, particularly useful in acute COPD exacerbations and severe asthma.", difficulty: "medium" },
  { topicId: 7, text: "Inhaled corticosteroids (ICS, e.g., fluticasone, budesonide) in asthma primarily act to:", options: ["Provide immediate bronchodilation", "Reduce airway inflammation, decreasing eosinophilic infiltration, mucus production, and airway hyperresponsiveness", "Block beta receptors", "Stimulate surfactant production"], correctIndex: 1, explanation: "ICS are the cornerstone controller therapy for persistent asthma. They reduce airway inflammation (reduce eosinophilia, mast cell activation, and cytokine production) but do NOT provide immediate bronchodilation.", difficulty: "easy" },
  { topicId: 7, text: "Oral corticosteroids in acute severe asthma exacerbations should be given because:", options: ["They cause immediate bronchodilation", "They reduce airway inflammation within hours, decreasing relapse rates, hospitalizations, and need for beta-agonists", "They increase lung compliance", "They prevent hypoxia"], correctIndex: 1, explanation: "Oral (or IV) corticosteroids in acute asthma: onset 4–6 hours, but accelerate resolution of airway inflammation, reduce relapse within 7 days, and decrease hospitalization rates. Early administration is critical.", difficulty: "medium" },
  { topicId: 7, text: "Magnesium sulfate (IV) in severe asthma exacerbations works by:", options: ["Blocking beta receptors", "Inhibiting calcium-mediated smooth muscle contraction causing bronchodilation", "Stimulating GABA receptors", "Blocking acetylcholine release"], correctIndex: 1, explanation: "Magnesium is a physiologic calcium antagonist. IV magnesium (2 g over 20 min) causes smooth muscle relaxation (bronchodilation and vasodilation) in severe acute asthma unresponsive to standard therapy.", difficulty: "medium" },
  { topicId: 7, text: "N-acetylcysteine (Mucomyst) is used as a mucolytic because:", options: ["It stimulates ciliary beat frequency", "It cleaves disulfide bonds in mucus glycoproteins, reducing mucus viscosity", "It is a bronchodilator", "It reduces airway inflammation"], correctIndex: 1, explanation: "NAC breaks disulfide bonds in mucin molecules, reducing mucus viscosity and improving mucociliary clearance. Used via nebulization or oral/IV for copious thick secretions, acetaminophen overdose (oral NAC).", difficulty: "medium" },
  { topicId: 7, text: "Dornase alfa (Pulmozyme) is used specifically in:", options: ["COPD", "Asthma", "Cystic fibrosis — it cleaves extracellular DNA in mucus, reducing viscosity", "Pulmonary fibrosis"], correctIndex: 2, explanation: "Dornase alfa is a recombinant human DNase I that cleaves the DNA released from dying neutrophils in CF mucus — the primary cause of its extreme viscosity. It reduces exacerbation frequency and improves lung function in CF.", difficulty: "medium" },
  { topicId: 7, text: "Methylxanthines (e.g., theophylline) cause bronchodilation by:", options: ["Beta-2 receptor agonism", "Inhibiting phosphodiesterase (increasing cAMP) and blocking adenosine receptors", "Inhibiting leukotriene synthesis", "Muscarinic receptor blockade"], correctIndex: 1, explanation: "Theophylline inhibits phosphodiesterase (preventing cAMP breakdown) and blocks adenosine receptors. It also has anti-inflammatory effects and improves diaphragmatic contractility. Narrow therapeutic window (10–20 mcg/mL) requires monitoring.", difficulty: "hard" },
  { topicId: 7, text: "Montelukast (Singulair) is a leukotriene receptor antagonist used in asthma primarily to:", options: ["Reverse acute bronchospasm", "Reduce allergen- and exercise-induced bronchoconstriction and inflammation as a controller medication", "Replace ICS in severe asthma", "Treat acute exacerbations"], correctIndex: 1, explanation: "Montelukast blocks cysteinyl leukotriene receptors, reducing allergen-triggered and exercise-induced bronchoconstriction, mucus secretion, and eosinophilic inflammation. It is a second-line controller, not a rescue medication.", difficulty: "medium" },
  { topicId: 7, text: "The main side effect of inhaled long-acting beta-agonists (LABAs, e.g., salmeterol) when used WITHOUT ICS in asthma is:", options: ["Severe hypertension", "Increased asthma mortality risk — LABAs must always be combined with ICS in asthma", "Severe hypoglycemia", "Oral candidiasis"], correctIndex: 1, explanation: "LABA monotherapy in asthma without ICS is contraindicated — FDA black box warning after SMART trial showing increased asthma-related deaths. LABAs must always be combined with ICS (e.g., Advair, Symbicort) in asthma.", difficulty: "hard" },
  { topicId: 7, text: "Tiotropium (Spiriva) is a long-acting muscarinic antagonist (LAMA) most commonly used for:", options: ["Acute asthma rescue", "Maintenance COPD management — once-daily bronchodilation", "Pediatric RSV treatment", "Pulmonary fibrosis"], correctIndex: 1, explanation: "Tiotropium is a once-daily LAMA that blocks muscarinic receptors for 24+ hours, reducing bronchoconstriction in COPD. The UPLIFT trial showed reduced exacerbations and improved quality of life.", difficulty: "easy" },
  { topicId: 7, text: "Epinephrine 1:1000 (IM) is the FIRST-LINE treatment for:", options: ["Severe asthma exacerbation", "Anaphylaxis — reverses bronchospasm, vasoconstriction, and angioedema", "COPD exacerbation", "Pulmonary embolism"], correctIndex: 1, explanation: "Epinephrine (adrenaline) 0.3–0.5 mg IM in the anterolateral thigh is first-line for anaphylaxis. It causes vasoconstriction (alpha-1), bronchodilation (beta-2), and cardiac stimulation (beta-1), reversing all key pathophysiology.", difficulty: "easy" },
  { topicId: 7, text: "Surfactant replacement therapy (e.g., beractant/Survanta) in preterm neonates with RDS is given via:", options: ["IV infusion", "Direct intratracheal instillation through the ETT", "Inhaled nebulization", "Subcutaneous injection"], correctIndex: 1, explanation: "Exogenous surfactant is instilled directly into the trachea via the ETT in preterm neonates with RDS. It distributes into the lungs with ventilator breaths, replacing deficient endogenous surfactant and reducing surface tension.", difficulty: "medium" },
  { topicId: 7, text: "Hypertonic saline (3–7%) nebulization is used in CF and bronchiectasis to:", options: ["Bronchodilate airways", "Hydrate the airway surface liquid, restoring mucociliary clearance", "Reduce airway inflammation directly", "Treat bacterial infections"], correctIndex: 1, explanation: "Inhaled hypertonic saline draws water into the airway lumen via osmosis, hydrating the dehydrated periciliary layer in CF (where CFTR dysfunction causes ASL dehydration), restoring mucociliary clearance.", difficulty: "medium" },
  { topicId: 7, text: "Ivacaftor (Kalydeco) and related CFTR modulators treat cystic fibrosis by:", options: ["Replacing the defective CFTR gene", "Correcting/potentiating the CFTR protein function directly — reducing mucus thickness at the cellular level", "Providing exogenous DNase", "Suppressing lung inflammation with steroids"], correctIndex: 1, explanation: "CFTR modulators (ivacaftor, lumacaftor, tezacaftor, elexacaftor) target the underlying CFTR protein defect — potentiating channel opening or correcting protein misfolding. They dramatically improve lung function in eligible CF genotypes.", difficulty: "hard" },
  { topicId: 7, text: "The mechanism of action of inhaled budesonide differs from albuterol in that budesonide:", options: ["Directly relaxes smooth muscle", "Acts on glucocorticoid receptors to reduce gene transcription of inflammatory mediators — onset hours vs. minutes for albuterol", "Has bronchodilatory effects within 5 minutes", "Only works systemically"], correctIndex: 1, explanation: "ICS like budesonide bind intracellular glucocorticoid receptors, altering gene transcription to reduce production of inflammatory cytokines. This process takes hours to days — not suitable for acute rescue use.", difficulty: "medium" },
  { topicId: 7, text: "Oral candidiasis (thrush) is a common side effect of inhaled corticosteroids. It can be minimized by:", options: ["Increasing the ICS dose", "Rinsing the mouth with water after each ICS dose and using a spacer device", "Switching to a different ICS class", "Using ICS only at night"], correctIndex: 1, explanation: "Rinsing the mouth and gargling after ICS use removes drug deposited in the oropharynx. A spacer (valved holding chamber) reduces oropharyngeal deposition by slowing particle velocity, further minimizing local side effects.", difficulty: "easy" },
  { topicId: 7, text: "Ketamine used as an induction agent for intubation in asthma is preferred because:", options: ["It depresses respiratory drive", "It is a bronchodilator (catecholamine release + direct smooth muscle relaxation), maintains airway reflexes, and provides hemodynamic stability", "It reduces secretions", "It is the fastest-onset agent available"], correctIndex: 1, explanation: "Ketamine causes catecholamine release → beta-2 stimulation → bronchodilation. It also directly relaxes bronchial smooth muscle. It maintains BP and respiratory drive (relatively), making it ideal for RSI in status asthmaticus.", difficulty: "medium" },
  { topicId: 7, text: "Which respiratory medication is given via MDI using a holding chamber (spacer) to improve:", options: ["Drug solubility", "Lower airway delivery by reducing impaction velocity and the need for hand-breath coordination", "Drug concentration", "Onset speed"], correctIndex: 1, explanation: "A spacer reduces drug velocity (particles slow down in the chamber), decreasing oropharyngeal impaction. It eliminates the need for perfect hand-breath coordination, critical for children and elderly patients.", difficulty: "easy" },

  // ── TOPIC 8: Patient Assessment & Monitoring ────────────────────────────
  { topicId: 8, text: "Accessory muscle use (SCM, scalene) during breathing in an adult patient indicates:", options: ["Normal breathing at rest", "Increased work of breathing — the diaphragm alone is insufficient", "Respiratory alkalosis", "High lung compliance"], difficulty: "easy", options: ["Normal breathing at rest", "Increased work of breathing — the diaphragm alone is insufficient", "Respiratory alkalosis", "High lung compliance"], correctIndex: 1, explanation: "Accessory muscle recruitment (sternocleidomastoid, scalene, pectorals) occurs when diaphragmatic work is insufficient to meet ventilatory demands — signifying significant respiratory distress.", difficulty: "easy" },
  { topicId: 8, text: "Kussmaul respirations are characterized by:", options: ["Slow shallow breaths", "Deep rapid regular breaths — compensatory hyperventilation for severe metabolic acidosis", "Irregular gasping breaths", "Alternating apnea and hyperpnea"], correctIndex: 1, explanation: "Kussmaul breathing: deep, rapid, regular respirations seen in severe metabolic acidosis (DKA, uremia). The respiratory center increases ventilation to blow off CO2 and compensate for the metabolic acidosis.", difficulty: "medium" },
  { topicId: 8, text: "Cheyne-Stokes respiration is characterized by:", options: ["Deep gasping with pauses", "Waxing-waning cycle of hyperpnea followed by apnea — associated with HF and neurological conditions", "Fixed shallow rapid breathing", "Deep regular breaths at high rate"], correctIndex: 1, explanation: "Cheyne-Stokes: cyclic crescendo-decrescendo breathing followed by central apnea. Associated with CHF (prolonged circulation time) and neurological injury. Circulation time from lungs to chemoreceptors is delayed.", difficulty: "medium" },
  { topicId: 8, text: "On percussion, a dull (flat) sound over a lung field indicates:", options: ["Hyperinflation or pneumothorax", "Consolidation, pleural effusion, or atelectasis", "Normal lung tissue", "Emphysema"], correctIndex: 1, explanation: "Percussion over airless tissue (consolidation, atelectasis) or fluid (pleural effusion) produces a dull (flat) sound. Hyperinflation and pneumothorax produce hyperresonant (tympanic) sounds. Normal lung = resonant.", difficulty: "easy" },
  { topicId: 8, text: "Crackles (rales) on auscultation are most commonly associated with:", options: ["Obstructive lung disease", "Fluid in the airways or interstitium — pulmonary edema, pneumonia, fibrosis, or atelectasis", "Tension pneumothorax", "Normal expiratory sound"], correctIndex: 1, explanation: "Crackles are caused by sudden opening of collapsed small airways (atelectasis, fibrosis) or fluid in airways (pulmonary edema, pneumonia). Fine crackles: fibrosis. Coarse crackles: fluid in larger airways.", difficulty: "easy" },
  { topicId: 8, text: "Stridor on inspiration indicates obstruction at the level of:", options: ["Small airways (bronchioles)", "Upper airway (supraglottic, glottic, or subglottic level)", "Alveoli", "Pleural space"], correctIndex: 1, explanation: "Inspiratory stridor (high-pitched crowing sound) indicates upper airway obstruction above the thoracic inlet — epiglottitis, croup, foreign body, post-extubation edema, anaphylaxis. Biphasic stridor suggests fixed obstruction.", difficulty: "easy" },
  { topicId: 8, text: "Paradoxical breathing (chest moves inward during inspiration) in a spontaneously breathing patient suggests:", options: ["Asthma exacerbation", "Severe flail chest or diaphragmatic weakness/paralysis", "Normal newborn breathing", "Pulmonary embolism"], correctIndex: 1, explanation: "Paradoxical chest wall motion occurs when a large flail segment (multiple rib fractures) is drawn inward by negative pleural pressure during inspiration, or when the diaphragm is paralyzed and the chest rises while the abdomen falls.", difficulty: "medium" },
  { topicId: 8, text: "Normal respiratory rate in an adult at rest is:", options: ["4–8 breaths/min", "12–20 breaths/min", "22–28 breaths/min", "30–40 breaths/min"], correctIndex: 1, explanation: "Normal adult respiratory rate: 12–20 breaths/min. Tachypnea (RR > 20) suggests distress, infection, or metabolic acidosis. Bradypnea (RR < 12) suggests narcosis, CNS depression, or fatigue.", difficulty: "easy" },
  { topicId: 8, text: "Capnography waveform (ETCO2) normally shows:", options: ["A flat line at 0", "Baseline (Phase I dead space), plateau (Phase II rise, Phase III alveolar plateau), and sudden drop to baseline at start of inspiration", "A continuously rising curve", "Random oscillations"], correctIndex: 1, explanation: "Normal capnogram: Phase I (zero — dead space exhalation), Phase II (rapid CO2 rise — mixed dead space/alveolar gas), Phase III (plateau ~35–45 mmHg — alveolar gas), then rapid fall at start of inspiration.", difficulty: "medium" },
  { topicId: 8, text: "On an EtCO2 waveform, a 'shark fin' or 'beaking' upstroke to Phase III (slow, rounded rise) in an asthmatic indicates:", options: ["Normal ventilation", "Airflow obstruction — slow, incomplete mixing of dead space and alveolar gas due to airway narrowing", "Esophageal intubation", "Increased dead space ventilation"], correctIndex: 1, explanation: "In obstructive disease, non-uniformly emptying lung units cause alveolar CO2 to mix slowly with dead space gas during exhalation, producing a slowly rising, 'shark fin' shaped Phase II–III transition rather than a sharp inflection.", difficulty: "hard" },
  { topicId: 8, text: "Pulse oximetry accuracy is reduced by all of the following EXCEPT:", options: ["Poor peripheral perfusion (low pulsatile flow)", "Dark skin pigmentation (minor effect; newer probes less affected)", "High-intensity ambient light", "Room air breathing (SpO2 95%)"], correctIndex: 3, explanation: "Room air breathing with SpO2 95% does not reduce oximetry accuracy — the device reads accurately here. Reduced accuracy: low perfusion/vasoconstriction, nail polish, severe anemia, motion artifact, and ambient light interference.", difficulty: "medium" },
  { topicId: 8, text: "A 12-lead ECG showing P pulmonale (tall peaked P waves > 2.5 mm in lead II) suggests:", options: ["Left ventricular hypertrophy", "Right atrial enlargement from chronic pulmonary hypertension or COPD", "Atrial fibrillation", "Left atrial enlargement"], correctIndex: 1, explanation: "P pulmonale (tall peaked P in leads II, III, aVF > 2.5 mm) indicates right atrial enlargement, seen with chronic pulmonary hypertension, COPD, or cor pulmonale from longstanding hypoxemia.", difficulty: "hard" },
  { topicId: 8, text: "Digital clubbing is associated with all of the following EXCEPT:", options: ["Lung cancer", "Bronchiectasis", "COPD without hypoxemia", "Cystic fibrosis"], correctIndex: 2, explanation: "Clubbing (loss of nail angle, boggy nail base, 'drumstick' fingers) is associated with chronic hypoxemia, lung cancer, bronchiectasis, CF, and chronic liver/cardiac disease. COPD without hypoxemia does NOT typically cause clubbing.", difficulty: "medium" },
  { topicId: 8, text: "Tracheal deviation toward the affected side is seen in:", options: ["Tension pneumothorax", "Large pleural effusion", "Atelectasis (lung collapse pulls trachea toward collapsed side)", "Pulmonary embolism"], correctIndex: 2, explanation: "Atelectasis (lung collapse) creates negative pleural pressure on the affected side, pulling the trachea toward the collapsed lung. Tension pneumothorax and large effusion push the trachea away from the affected side.", difficulty: "medium" },
  { topicId: 8, text: "A normal A-a gradient with hypoxemia (low PaO2, normal PAO2 − PaO2) indicates that hypoxemia is caused by:", options: ["V/Q mismatch", "Intrapulmonary shunt", "Hypoventilation — the lungs are working normally; the problem is insufficient ventilation reaching the alveoli", "Diffusion impairment"], correctIndex: 2, explanation: "If PaO2 is low but the A-a gradient is normal, the alveolar PO2 is also low — meaning not enough fresh gas is reaching the alveoli (hypoventilation). The lung's own gas exchange ability is intact.", difficulty: "hard" },
  { topicId: 8, text: "The bicarbonate (HCO3−) concentration can be estimated from an ABG using the Henderson-Hasselbalch equation. Alternatively, a quick bedside rule is that HCO3 decreases by approximately __ mEq/L for every 10 mmHg rise in PaCO2 in ACUTE respiratory acidosis:", options: ["1 mEq/L", "3.5 mEq/L", "5 mEq/L", "10 mEq/L"], correctIndex: 0, explanation: "In acute respiratory acidosis, HCO3 rises by ~1 mEq/L per 10 mmHg rise in PaCO2 (buffering by non-bicarbonate buffers — hemoglobin, proteins). In chronic: ~3.5 mEq/L per 10 mmHg (renal compensation).", difficulty: "hard" },
  { topicId: 8, text: "On a chest X-ray, an infiltrate in the right lower lobe with an air bronchogram is most consistent with:", options: ["Pleural effusion", "Pneumothorax", "Pneumonia or atelectasis with patent bronchi", "Pulmonary edema (bilateral)"], correctIndex: 2, explanation: "Air bronchograms (air-filled bronchi visible within an opacified area) indicate alveolar opacification with patent airways — classic for pneumonia or non-obstructive atelectasis. They are NOT seen in pleural effusion or pneumothorax.", difficulty: "medium" },
  { topicId: 8, text: "Which physical examination finding is associated with decreased tactile fremitus AND dullness to percussion?", options: ["Consolidation (pneumonia)", "Pleural effusion", "Pneumothorax", "Atelectasis"], correctIndex: 1, explanation: "Pleural effusion: dullness to percussion (fluid) + decreased fremitus (fluid damps transmission). Consolidation: dullness + increased fremitus (solid tissue transmits vibrations better). Pneumothorax: hyperresonance + decreased fremitus.", difficulty: "hard" },
  { topicId: 8, text: "Bronchial breath sounds heard over a peripheral lung region (instead of vesicular sounds) indicate:", options: ["Normal finding", "Consolidation (sound transmits through airless solid tissue like a bronchus)", "Pleural effusion", "Emphysema"], correctIndex: 1, explanation: "Bronchial (tubular) breath sounds (loud, hollow, high-pitched with equal I:E ratio) heard over peripheral lung indicate consolidation — the airless parenchyma transmits sound from central airways unchanged, like listening directly over a bronchus.", difficulty: "medium" },
  { topicId: 8, text: "The most common early sign of impending respiratory failure in a patient with neuromuscular disease (e.g., GBS, ALS) is:", options: ["Declining SpO2", "Rising PaCO2 on ABG", "Decreasing FVC toward 15–20 mL/kg (Rule of 20-30-40)", "Increasing respiratory rate"], correctIndex: 2, explanation: "In NMD, FVC decline is the earliest sign of respiratory muscle weakness. Elective intubation thresholds: FVC < 20 mL/kg, NIF < −30 cmH₂O, or peak cough flow < 270 L/min ('20-30-40 rule'). SpO2 and PaCO2 are late signs.", difficulty: "hard" },

  // ── TOPIC 9: Neonatal & Pediatric Respiratory Care ───────────────────────
  { topicId: 9, text: "Respiratory distress syndrome (RDS) in preterm neonates is caused by:", options: ["Bacterial infection", "Surfactant deficiency — immature type II pneumocytes cannot produce adequate surfactant before ~35 weeks gestation", "Meconium aspiration", "Congenital diaphragmatic hernia"], correctIndex: 1, explanation: "RDS (formerly hyaline membrane disease) is caused by surfactant deficiency in premature lungs. Without surfactant, alveolar surface tension is high, causing progressive atelectasis, hypoxemia, and respiratory failure.", difficulty: "easy" },
  { topicId: 9, text: "Antenatal corticosteroids (betamethasone) given to mothers at risk of preterm birth accelerate:", options: ["Fetal heart rate", "Fetal lung maturity — stimulating surfactant production by type II pneumocytes", "Neonatal immune response", "Placental blood flow"], correctIndex: 1, explanation: "Antenatal betamethasone (2 doses 24 hrs apart) accelerates fetal lung maturity by upregulating surfactant synthesis. Most effective at 24–34 weeks gestation; reduces RDS severity, IVH, and neonatal mortality.", difficulty: "medium" },
  { topicId: 9, text: "nCPAP (nasal CPAP) in premature neonates with RDS works primarily by:", options: ["Delivering high FiO2", "Maintaining alveolar patency with continuous positive pressure, reducing FiO2 requirements and work of breathing", "Providing positive pressure breaths", "Administering surfactant"], correctIndex: 1, explanation: "nCPAP maintains FRC by keeping alveoli open throughout the breath cycle, reducing V/Q mismatch and shunt. INSURE (Intubate-Surfactant-Extubate) strategies use brief intubation for surfactant then rapid extubation to nCPAP.", difficulty: "medium" },
  { topicId: 9, text: "Transient tachypnea of the newborn (TTN) is caused by:", options: ["Surfactant deficiency", "Delayed clearance of fetal lung fluid, particularly after C-section (no labor compression of the chest)", "Group B Streptococcal pneumonia", "Pulmonary hypoplasia"], correctIndex: 1, explanation: "TTN ('wet lung') results from delayed resorption of fetal lung fluid. Labor contractions normally squeeze fluid from the lungs via the thorax. C-section without labor, especially preterm, increases TTN risk. It resolves in 24–72 hours.", difficulty: "medium" },
  { topicId: 9, text: "Meconium aspiration syndrome (MAS) causes respiratory failure due to:", options: ["Surfactant deficiency only", "Ball-valve airway obstruction causing air trapping + chemical pneumonitis + surfactant inactivation", "Bacterial sepsis", "Pulmonary hypertension alone"], correctIndex: 1, explanation: "Meconium causes: partial airway obstruction (ball-valve → air trapping), complete obstruction (atelectasis), chemical pneumonitis, surfactant inactivation, and persistent pulmonary hypertension (PPHN) — a complex, multifactorial syndrome.", difficulty: "hard" },
  { topicId: 9, text: "Persistent pulmonary hypertension of the newborn (PPHN) is treated with:", options: ["Oxygen restriction", "High FiO2, inhaled nitric oxide, and sometimes ECMO — to reduce pulmonary vascular resistance and improve oxygenation", "Beta-blockers", "Surfactant only"], correctIndex: 1, explanation: "PPHN: right-to-left shunting through the ductus arteriosus and foramen ovale due to elevated PVR. Treatment: optimize oxygenation (high FiO2), alkalosis (increase pH), iNO (selective pulmonary vasodilator), and ECMO for refractory cases.", difficulty: "medium" },
  { topicId: 9, text: "Infant respiratory rate and tidal volume differ from adults in that infants have:", options: ["Slower respiratory rate (8–12/min) and larger tidal volumes", "Faster respiratory rate (30–60/min) and smaller tidal volumes (6–8 mL/kg)", "Same rates but smaller tidal volume", "Lower RR with equal tidal volume to adults"], correctIndex: 1, explanation: "Newborn normal RR: 30–60/min. Tidal volume ~6–8 mL/kg. Infants compensate for their high metabolic rate with increased respiratory rate rather than larger tidal volumes — their chest wall compliance is high and ribs are more horizontal.", difficulty: "easy" },
  { topicId: 9, text: "RSV (Respiratory Syncytial Virus) bronchiolitis in infants presents with:", options: ["Stridor and croup", "Wheezing, crackles, hyperinflation, and hypoxemia — lower airway obstruction from bronchiolar inflammation", "Lobar consolidation", "Only upper respiratory symptoms"], correctIndex: 1, explanation: "RSV bronchiolitis: inflammation of small bronchioles → mucus plugging → air trapping (hyperinflation on CXR) and atelectasis → wheezing, crackles, tachypnea, and hypoxemia. Most common cause of infant hospitalization.", difficulty: "medium" },
  { topicId: 9, text: "Croup (laryngotracheobronchitis) is most commonly caused by:", options: ["Streptococcal bacteria", "Parainfluenza virus — causing subglottic mucosal edema and a 'barking' cough with inspiratory stridor", "RSV", "Influenza A"], correctIndex: 1, explanation: "Croup: parainfluenza virus (types 1, 2, 3) causes subglottic inflammation and edema → classic 'seal bark' cough, inspiratory stridor, and steeple sign on neck X-ray. Racemic epinephrine nebulization + dexamethasone are treatments.", difficulty: "medium" },
  { topicId: 9, text: "Pediatric endotracheal tube size can be estimated using the Broselow tape or the formula:", options: ["Age + 10 / 4", "(Age in years / 4) + 4 for uncuffed ETT", "Weight / 10", "Height / 30"], correctIndex: 1, explanation: "Uncuffed ETT size = (Age/4) + 4. Cuffed ETT = (Age/4) + 3.5. For example, a 4-year-old: uncuffed = 4/4 + 4 = 5.0 mm. Always verify: the tube should pass the cords with a small leak at 20–25 cmH₂O.", difficulty: "medium" },
  { topicId: 9, text: "Epiglottitis (acute supraglottitis) in children is a medical emergency because:", options: ["It causes lower airway obstruction", "Rapid, severe supraglottic swelling can cause total airway obstruction — DO NOT examine the oropharynx in the ED without airway team present", "It is caused by a toxin, not inflammation", "It improves spontaneously within hours"], correctIndex: 1, explanation: "Epiglottitis (historically Haemophilus influenzae type b, now often Streptococcal) causes rapid supraglottic edema. The child should be kept calm and taken directly to the OR for controlled intubation — agitation can cause complete obstruction.", difficulty: "medium" },
  { topicId: 9, text: "Bronchopulmonary dysplasia (BPD) in premature neonates is defined as oxygen dependence beyond:", options: ["24 hours of life", "72 hours of life", "28 days of life (or 36 weeks corrected GA)", "3 months of life"], correctIndex: 2, explanation: "BPD (now called 'new BPD') is defined as supplemental oxygen requirement at 28 days of life (mild) or at 36 weeks postmenstrual age (moderate/severe). It results from lung immaturity, oxygen toxicity, and ventilator-induced injury.", difficulty: "medium" },
  { topicId: 9, text: "Congenital diaphragmatic hernia (CDH) causes respiratory failure primarily due to:", options: ["Surfactant deficiency", "Ipsilateral pulmonary hypoplasia and pulmonary hypertension from herniated abdominal organs compressing the developing lung", "Meconium aspiration", "Tracheomalacia"], correctIndex: 1, explanation: "CDH: defect in the diaphragm allows abdominal organs to herniate into the chest during fetal development, compressing the developing lung and causing pulmonary hypoplasia and severe PPHN — a major surgical and respiratory challenge.", difficulty: "hard" },
  { topicId: 9, text: "Apnea of prematurity (AOP) is treated with:", options: ["Inhaled bronchodilators", "Methylxanthines (caffeine citrate) — stimulate central respiratory drive by adenosine receptor blockade", "Surfactant replacement", "Sedation"], correctIndex: 1, explanation: "Caffeine citrate (20 mg/kg load, 5 mg/kg/day maintenance) is the first-line treatment for AOP, stimulating central respiratory drive. It reduces apneic spells, improves extubation success, and has a favorable neurodevelopmental safety profile.", difficulty: "medium" },
  { topicId: 9, text: "Which maneuver is performed during neonatal resuscitation if the infant remains bradycardic (HR < 60) despite adequate PPV and chest compressions?", options: ["Epinephrine (IV or ET)", "Surfactant administration", "Cooling (therapeutic hypothermia)", "Dexamethasone"], correctIndex: 0, explanation: "NRP algorithm: if HR < 60 despite adequate PPV + chest compressions → IV/IO epinephrine (0.01–0.03 mg/kg). ET epinephrine is less preferred (poor absorption) but can be used at 0.05–0.10 mg/kg while IV access is established.", difficulty: "medium" },
  { topicId: 9, text: "The lecithin-to-sphingomyelin (L/S) ratio in amniotic fluid is used to assess:", options: ["Fetal heart development", "Fetal lung maturity — L/S ≥ 2.0 indicates mature surfactant production (unlikely to develop RDS)", "Maternal blood type", "Placental function"], correctIndex: 1, explanation: "Lecithin (phosphatidylcholine) is a major surfactant component that increases as the lung matures. The L/S ratio ≥ 2.0 in amniotic fluid indicates fetal lung maturity. Addition of PG (phosphatidylglycerol) improves specificity.", difficulty: "medium" },
  { topicId: 9, text: "High-frequency jet ventilation (HFJV) in neonates is preferred over conventional MV in which condition?", options: ["Uncomplicated RDS", "Pulmonary interstitial emphysema (PIE) or air leak syndromes — low mean airway pressure reduces further barotrauma", "Meconium aspiration", "Apnea of prematurity"], correctIndex: 1, explanation: "HFJV delivers very small tidal volumes at 240–600 breaths/min, achieving gas exchange at very low peak airway pressures. This is particularly beneficial in PIE and air leak syndromes where reducing airway pressure is critical.", difficulty: "hard" },
  { topicId: 9, text: "In the Apgar score, a score of 7–10 at 1 minute indicates:", options: ["Need for immediate resuscitation", "Mild depression — routine care", "Good neonatal adaptation — routine care", "Severe depression"], correctIndex: 2, explanation: "Apgar score (A-Appearance, P-Pulse, G-Grimace, A-Activity, R-Respirations): 7–10 = vigorous neonate, routine care; 4–6 = moderate depression, stimulate and possibly assist ventilation; 0–3 = severe depression, full resuscitation.", difficulty: "easy" },
  { topicId: 9, text: "In pediatric patients, the most common cause of cardiac arrest is:", options: ["Primary cardiac dysrhythmia (like adults)", "Respiratory failure or shock leading to hypoxic arrest", "Pulmonary embolism", "Hypertensive emergency"], correctIndex: 1, explanation: "Unlike adults (primary cardiac arrest from dysrhythmia), most pediatric arrests are secondary — caused by respiratory failure or shock that progresses to hypoxia and hypoperfusion. This is why airway and breathing are the highest priority in pediatric resuscitation.", difficulty: "medium" },
  { topicId: 9, text: "Surfactant replacement therapy in neonatal RDS is most effective when given:", options: ["After 24 hours of life", "Early in the disease course (prophylactic or early rescue — within the first 2 hours of life)", "Only as rescue when FiO2 > 0.90", "Via nebulized route"], correctIndex: 1, explanation: "Early surfactant administration (prophylactic at birth or rescue within 2 hours in intubated infants with FiO2 > 0.30–0.40) achieves the best outcomes. Delayed administration allows progressive lung injury from high surface tension.", difficulty: "medium" },
  { topicId: 9, text: "The most common complication of mechanical ventilation in premature neonates is:", options: ["Tension pneumothorax", "Ventilator-induced lung injury (VILI) — leading to air leak syndromes (pneumothorax, PIE, pneumomediastinum) and contributing to BPD", "Accidental extubation", "ETT obstruction"], correctIndex: 1, explanation: "VILI from overdistension (volutrauma) and high pressures (barotrauma) is the primary ventilator complication in premature neonates, causing air leaks and contributing to BPD. Lung-protective ventilation with optimal PEEP and low TV is essential.", difficulty: "medium" },

  // ── TOPIC 10: Critical Care & Emergency Respiratory ──────────────────────
  { topicId: 10, text: "Type I (hypoxemic) respiratory failure is defined as:", options: ["PaO2 < 60 mmHg with elevated PaCO2", "PaO2 < 60 mmHg on room air with normal or low PaCO2", "Any PaO2 < 80 mmHg", "PaCO2 > 45 mmHg regardless of PaO2"], correctIndex: 1, explanation: "Type I respiratory failure: PaO2 < 60 mmHg with PaCO2 normal or low (< 45 mmHg). The problem is oxygenation (V/Q mismatch, shunt, diffusion impairment) — ARDS, pneumonia, PE, pulmonary edema. PaCO2 is often low due to compensatory hyperventilation.", difficulty: "medium" },
  { topicId: 10, text: "In massive pulmonary embolism causing obstructive shock, first-line treatment is:", options: ["High-dose diuretics", "Systemic thrombolysis (tPA) or catheter-directed thrombolysis/thrombectomy — rapidly reducing RV afterload", "Norepinephrine infusion alone", "Bronchodilators"], correctIndex: 1, explanation: "Massive PE with hemodynamic collapse: systemic thrombolysis (alteplase 100 mg over 2 hrs) is the treatment of choice when there is no absolute contraindication. It rapidly reduces clot burden, lowering RV afterload and restoring cardiac output.", difficulty: "medium" },
  { topicId: 10, text: "The three criteria for SIRS (Systemic Inflammatory Response Syndrome) diagnosis include all EXCEPT:", options: ["Temperature > 38°C or < 36°C", "Heart rate > 90/min", "Respiratory rate > 20/min or PaCO2 < 32 mmHg", "PaO2 < 60 mmHg"], correctIndex: 3, explanation: "SIRS criteria (2 of 4): (1) Temp > 38°C or < 36°C, (2) HR > 90, (3) RR > 20 or PaCO2 < 32, (4) WBC > 12,000 or < 4,000 or > 10% bands. PaO2 < 60 mmHg is NOT a SIRS criterion (though important in ARDS).", difficulty: "hard" },
  { topicId: 10, text: "Tension pneumothorax treatment before imaging is:", options: ["Wait for portable CXR confirmation", "Immediate needle decompression (2nd ICS MCL) followed by chest tube placement", "Place chest tube immediately without needle decompression", "Non-rebreather mask and observation"], correctIndex: 1, explanation: "Tension pneumothorax is a clinical diagnosis requiring immediate decompression — do NOT delay for imaging if the patient is hemodynamically unstable. Needle decompression (2nd ICS, MCL or 4th/5th ICS, MAL) must be followed by chest tube.", difficulty: "medium" },
  { topicId: 10, text: "The respiratory component of 'sepsis-induced ARDS' differs from direct (pulmonary) ARDS in that:", options: ["Indirect ARDS has better lung compliance initially", "Both are indistinguishable clinically", "Indirect ARDS tends to have better compliance and more recruitable lung", "Indirect ARDS has worse outcomes"], correctIndex: 2, explanation: "Indirect (extrapulmonary) ARDS from sepsis/pancreatitis tends to have better lung compliance and more recruitable atelectasis than direct (pulmonary) ARDS from pneumonia. Higher PEEP and recruitment may be more beneficial in indirect ARDS.", difficulty: "hard" },
  { topicId: 10, text: "Drowning resuscitation differs from standard cardiac arrest in that:", options: ["CPR is not indicated", "Ventilation is the priority — submersion arrests are primarily hypoxic; 5 rescue breaths before starting compressions per most guidelines", "Atropine is first-line", "Defibrillation should be performed immediately before ventilation"], correctIndex: 1, explanation: "Drowning arrests are hypoxic in origin. Rescue breathing (5 initial breaths) before chest compressions is emphasized in drowning protocols, as oxygenation is the primary need — unlike VF cardiac arrest where early defibrillation is paramount.", difficulty: "medium" },
  { topicId: 10, text: "Carbon monoxide (CO) poisoning treatment is:", options: ["Low-flow nasal cannula oxygen", "100% O2 via NRB mask (or hyperbaric oxygen in severe cases) to competitively displace CO from hemoglobin", "IV bicarbonate", "Bronchodilators"], correctIndex: 1, explanation: "CO has 250× higher affinity for hemoglobin than O2. 100% O2 reduces COHb half-life from ~5 hours (room air) to 60–90 minutes. HBO further reduces it to 20–30 minutes and is indicated in severe poisoning (loss of consciousness, cardiac involvement, high COHb).", difficulty: "medium" },
  { topicId: 10, text: "Status asthmaticus is defined as:", options: ["Any asthma exacerbation requiring an inhaler", "Severe asthma that fails to respond to initial bronchodilator therapy — risk of respiratory failure requiring escalated treatment", "Asthma with SpO2 < 95%", "Any asthma requiring oral steroids"], correctIndex: 1, explanation: "Status asthmaticus: severe, prolonged asthma exacerbation unresponsive to initial standard therapy (repeated doses of SABA, ipratropium, systemic steroids). Risk of respiratory failure requiring ICU management and possibly mechanical ventilation.", difficulty: "medium" },
  { topicId: 10, text: "Indications for emergency intubation in status asthmaticus include:", options: ["Any wheeze with SpO2 < 95%", "Respiratory arrest, severe exhaustion (unable to speak), altered mental status, or PaCO2 rising despite maximum therapy", "First failed nebulizer treatment", "Mild accessory muscle use"], correctIndex: 1, explanation: "Intubation in status asthmaticus is a last resort due to high risks (barotrauma, hemodynamic compromise). Indications: imminent respiratory arrest, AMS, severe fatigue, or worsening hypercapnia despite maximum therapy.", difficulty: "medium" },
  { topicId: 10, text: "Flail chest occurs when:", options: ["The sternum fractures", "Three or more adjacent ribs are fractured in two places, creating a free-floating segment that moves paradoxically", "The clavicle fractures bilaterally", "A single rib fractures in two places only"], correctIndex: 1, explanation: "Flail chest: ≥ 3 adjacent ribs fractured in ≥ 2 places each, creating a free segment. During inspiration, negative pressure draws the flail segment inward (paradoxical movement), impairing ventilation. The underlying pulmonary contusion is the major cause of hypoxemia.", difficulty: "medium" },
  { topicId: 10, text: "In acute respiratory failure from obesity hypoventilation syndrome (OHS), which ventilatory support is first-line?", options: ["High-flow nasal cannula at 60 L/min", "Non-invasive positive pressure ventilation (NIV/BiPAP) — corrects hypercapnia and improves oxygenation", "HFOV", "Volume-cycled SIMV"], correctIndex: 1, explanation: "OHS (Pickwickian syndrome) with acute hypercapnic failure responds well to NIV (BiPAP) — inspiratory support reduces work of breathing and EPAP (expiratory positive pressure) maintains upper airway patency and FRC. It avoids intubation in most cases.", difficulty: "medium" },
  { topicId: 10, text: "Neurogenic pulmonary edema (NPE) following traumatic brain injury occurs due to:", options: ["Direct aspiration of fluid", "Massive sympathetic discharge causing systemic vasoconstriction, fluid shift, and pulmonary capillary injury", "Pneumonia from aspiration", "Depressed cough reflex only"], correctIndex: 1, explanation: "NPE: catastrophic neurological events (TBI, SAH, seizures) trigger massive sympathetic surges → systemic vasoconstriction → fluid redistribution to pulmonary circulation → high hydrostatic pressure and capillary injury → pulmonary edema.", difficulty: "hard" },
  { topicId: 10, text: "The Surviving Sepsis Campaign recommends which initial oxygen target in septic shock?", options: ["Maintain SpO2 ≥ 99%", "Maintain SpO2 92–96% (or PaO2 65–70 mmHg) to avoid both hypoxemia and hyperoxia", "SpO2 ≥ 88% only", "No specific oxygen target"], correctIndex: 1, explanation: "Surviving Sepsis Campaign 2021: target SpO2 92–96% in adults. Avoid hypoxia (SpO2 < 90%) but also avoid hyperoxia (SpO2 > 96%–99%), as liberal oxygen therapy may worsen mortality.", difficulty: "hard" },
  { topicId: 10, text: "In high-altitude illness, hypoxemia is caused by:", options: ["Increased FiO2 at altitude", "Reduced barometric pressure lowering PAO2 despite normal FiO2 (21%)", "Nitrogen narcosis", "Increased CO2 at altitude"], correctIndex: 1, explanation: "At altitude, FiO2 remains 21%, but barometric pressure is reduced. PAO2 = 0.21 × (Pb − 47). At 8,000 ft (Pb ~560 mmHg): PAO2 = 0.21 × 513 ≈ 108 mmHg. At 29,029 ft (Everest, Pb ~253): PAO2 ≈ 43 mmHg — barely above hypoxic threshold.", difficulty: "medium" },
  { topicId: 10, text: "The initial ventilator setting concern in a patient with traumatic brain injury (TBI) on MV is:", options: ["Maximizing PEEP to improve oxygenation", "Avoid hypoxemia (PaO2 ≥ 60) AND hypercapnia — both worsen intracranial pressure and secondary brain injury", "Permissive hypercapnia is acceptable", "Aggressive hyperventilation to reduce ICP"], correctIndex: 1, explanation: "TBI ventilation goals: SpO2 ≥ 95%, PaO2 ≥ 80 mmHg, PaCO2 35–40 mmHg (normocapnia). Hypoxemia worsens secondary injury. Hypercapnia causes cerebral vasodilation → increased ICP. Brief hyperventilation (PaCO2 30–35) only for acute herniation.", difficulty: "hard" },
];

async function main() {
  const existing = await pool.query("SELECT COUNT(*) FROM questions WHERE topic_id != 4");
  console.log(`Existing non-MV questions: ${existing.rows[0].count}`);
  console.log(`Inserting ${questions.length} general questions...`);
  for (const q of questions) {
    await pool.query(
      `INSERT INTO questions (topic_id, text, options, correct_index, explanation, difficulty) VALUES ($1,$2,$3,$4,$5,$6)`,
      [q.topicId, q.text, JSON.stringify(q.options), q.correctIndex, q.explanation, q.difficulty]
    );
  }
  const final = await pool.query("SELECT topic_id, COUNT(*) FROM questions WHERE topic_id != 4 GROUP BY topic_id ORDER BY topic_id");
  console.log("New non-MV question counts:", final.rows.map(r => `T${r.topic_id}:${r.count}`).join(", "));
  const totalAdded = await pool.query("SELECT COUNT(*) FROM questions");
  console.log(`Total questions in bank: ${totalAdded.rows[0].count}`);
  await pool.end();
}

main().catch(err => { console.error(err); process.exit(1); });
